import {cacDropout} from './dropout.js';
import {TODAY,centres,seed,operatingDates,attendanceBand,activityBand,examBand,seedMorarjiHistory} from './data.js';
const $=s=>document.querySelector(s), KEY='mass-cac-companion-v1';
const liveReview=Boolean(globalThis.__massLiveReviewData);let db=globalThis.__massLiveReviewData; if(!liveReview){try{db=JSON.parse(localStorage.getItem(KEY));}catch{}if(!db?.version)db=seed();}if(!db.sessions)db.sessions=liveReview?[]:seed().sessions;if(!db.morarjiHistory)db.morarjiHistory=liveReview?[]:seedMorarjiHistory();if(!db.assessmentDetails)db.assessmentDetails={};if(!db.assessmentBatches)db.assessmentBatches={};
const state={role:'Leadership',page:'overview',month:TODAY.slice(0,7),date:TODAY,centre:'',shift:'',grade:'',gender:'',donor:'',officer:'',exam:'F2',morarjiYear:'2025–26',query:'',concerns:false,engagementFilter:'',menu:false,fromExam:'F1',toExam:'F2',comparison:'F1|F2',collapsed:false,laterModules:false};
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-3.87',calendar:'M4 5h16v16H4Z M16 3v4 M8 3v4 M4 11h16 M8 15h2 M14 15h2',chart:'M4 3v18h17 M8 17v-5 M13 17V7 M18 17V4',activity:'M12 3 15 9l7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',book:'M12 6c-3-3-7-3-10-2v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2Z M12 6v15',visit:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M12 13a3 3 0 1 0 0-6 3 3 0 0 0 0 6',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12 M6 18 18 6',menu:'M4 6h16 M4 12h16 M4 18h16',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',flag:'M4 22V3c5-3 10 3 16 0v11c-6 3-11-3-16 0',filter:'M3 5h18l-7 8v7l-4-2v-5Z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z'};
const icon=n=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.chart}"/></svg>`;
const badge=(label,tone='muted')=>`<span class="badge ${tone}">${esc(label)}</span>`;
const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const monthName=()=>new Date(state.month+'-01T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function persist(message){if(liveReview)throw new Error('For real data entry, use the secure operational workspace rather than this read-only review.');if(typeof removalUndo!=='undefined')removalUndo=null;db.lastSaved=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('Browser storage is full. Export your records before leaving.');return;}if(message)toast(message);}
function scope(){return centres.filter(c=>(liveReview||((state.role!=='Teacher'||c.id==='C01')&&(state.role!=='Cluster Officer'||c.officer==='Meera')))&&(!state.centre||c.id===state.centre)&&(!state.donor||c.donor===state.donor)&&(!state.officer||c.officer===state.officer));}
function children(ignoreGender=false){const ids=scope().map(c=>c.id),when=state.page==='daily'?state.date:state.month+'-01';return db.students.filter(s=>(s.active||s.exitDate>=when)&&ids.includes(s.centre)&&(!state.shift||s.shift===state.shift)&&(ignoreGender||!state.gender||s.gender===state.gender));}
const centreName=id=>centres.find(c=>c.id===id)?.name||id;
function scoreInfo(s,ex=state.exam){const meta=db.assessmentDetails?.[s.id+'|'+ex]||{},score=db.scores[s.id]?.[ex]??null;return {score,maxMarks:meta.maxMarks??25,date:meta.date||'',performance:meta.performance||'',status:meta.status||(score===null?'Not entered':'Recorded'),sample:!meta.maxMarks};}
function scoreGroup(list,ex=state.exam){const values=list.map(c=>scoreInfo(c,ex)).filter(r=>r.score!==null),maxima=[...new Set(values.map(r=>r.maxMarks))];return {n:values.length,max:maxima.length===1?maxima[0]:null,avg:values.length&&maxima.length===1?+(values.reduce((a,r)=>a+r.score,0)/values.length).toFixed(1):null};}
function recordedBand(r){return r.status==='Absent'?{label:'Absent from exam',tone:'muted'}:r.score===null?examBand(null):r.maxMarks!==25?{label:'Scale to review',tone:'muted'}:examBand(r.score);}
function stats(s){const recorded=liveReview?(globalThis.__massReviewObservedDatesByCentre?.[s.centre]?.[state.month]||[]):operatingDates(state.month);const days=recorded.filter(d=>d>=s.enrolled);let p=0,a=0,h=0,missing=0;days.forEach(d=>{const v=db.attendance[s.id+'|'+d];if(v==='P')p++;else if(v==='A')a++;else if(['H','WO','MM'].includes(v))h++;else if(v==='L'){}else missing++;});const events=db.events.filter(e=>e.centre===s.centre&&e.date.startsWith(state.month)&&e.status==='Held'&&e.date>=s.enrolled&&(!e.shift||e.shift==='Both shifts'||e.shift===s.shift));let act=0,unknown=0,coreAct=0,coreUnknown=0;events.forEach(e=>{const v=db.participation[s.id+'|'+e.id];if(v==='Attended'){act++;if(['Cultural','Sports'].includes(e.category))coreAct++;}else if(v!=='Not attended'){unknown++;if(['Cultural','Sports'].includes(e.category))coreUnknown++;}});const assessment=scoreInfo(s);return {p,a,h,missing,days:days.length,act,unknown,coreAct,coreUnknown,held:events.length,...assessment,good:p>20&&coreAct>=2&&!missing&&!coreUnknown};}
function totals(list=children()){const rows=list.map(s=>({s,...stats(s)}));return {rows,p:rows.reduce((a,r)=>a+r.p,0),a:rows.reduce((a,r)=>a+r.a,0),missing:rows.reduce((a,r)=>a+r.missing,0),good:rows.filter(r=>r.good).length,low:rows.filter(r=>r.days>0&&r.p<15&&!r.missing).length};}
function navItems(){if(state.page==='donor')return [['donor','Donor overview','heart']];if(state.role==='Teacher')return [['overview','Overview','home'],['daily','Daily Attendance','calendar'],['children','Student Profile','people'],['learning','Learning','book'],['activities','Activities','activity'],['morarji','Morarji scholarship prep','chart'],...(state.laterModules?[['guidance','Career Guidance','flag']]:[])];if(state.role==='Cluster Officer')return [['overview','My Centres','home'],['children','Student Profile','people'],['visits','Visits','visit'],['attendance','Attendance','calendar'],['learning','Learning','book'],['activities','Activities','activity'],['morarji','Morarji scholarship prep','chart'],...(state.laterModules?[['guidance','Career Guidance','flag']]:[])];return [['overview','Overview','home'],['attendance','Attendance','calendar'],['learning','Learning','book'],['activities','Activities & Engagement','activity'],['morarji','Morarji scholarship prep','chart'],['visits','Officer Visits','visit']];}
function select(label,key,options,placeholder='All'){return `<label class="filter"><span>${label}</span><select data-filter="${key}" aria-label="${label}">${placeholder!==null?`<option value="">${placeholder}</option>`:''}${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${state[key]===v?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function filters({simple=false,cohort=false}={}){const cs=centres.filter(c=>(liveReview||((state.role!=='Teacher'||c.id==='C01')&&(state.role!=='Cluster Officer'||c.officer==='Meera')))&&(!liveReview||!state.donor||c.donor===state.donor)),learning=state.page==='learning';const selectable=db.students.filter(s=>cs.some(c=>c.id===s.centre));const gradeOptions=[...new Set(selectable.map(s=>s.grade).filter(Boolean))].sort((a,b)=>Number(a)-Number(b));const shiftOptions=[...new Set(selectable.map(s=>s.shift).filter(Boolean))].sort();const genderOptions=[...new Set(selectable.map(s=>s.gender).filter(Boolean))].sort();return `<div class="filters">${!cohort&&!learning?select('Reporting month','month',liveReview?[['2026-07','July 2026'],['2026-08','August 2026'],['2026-09','September 2026'],['2026-10','October 2026']]:[['2026-09','September 2026'],['2026-10','October 2026']],null):''}${(liveReview||state.role!=='Teacher')?select('Centre','centre',cs.map(c=>[c.id,c.name]),'All centres'):''}${!simple?select('Shift','shift',liveReview?shiftOptions:['Morning','Evening'],'Both shifts'):''}${liveReview&&!simple?select('Grade','grade',gradeOptions,'All grades')+select('Gender','gender',genderOptions,'All genders'):''}${state.role==='Leadership'&&['overview','donor'].includes(state.page)?select('Donor','donor',[...new Set(centres.map(c=>c.donor))],'All donors'):''}${state.page==='visits'&&state.role==='Leadership'?select('Cluster Officer','officer',[...new Set(cs.map(c=>c.officer))],'All officers'):''}${learning?select('Exam round','exam',['F1','F2','F3','F4'],null):''}<button class="reset-filter" data-action="reset-filters">Reset filters</button><span class="filter-note">${learning?`${state.exam} results`:cohort?state.morarjiYear:monthName()} · ${state.centre?centreName(state.centre):state.role==='Teacher'?'Your centre':'All permitted centres'}${state.officer?' · '+state.officer:''}${state.month===TODAY.slice(0,7)&&!learning&&!cohort?' · month to date':''}</span>${state.gender?`<button class="filter-chip" data-gender="${state.gender}">${state.gender==='Girl'?'Girls':'Boys'} only · clear ×</button>`:''}</div>`;}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">Children’s Activity Centres</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;}
function button(text,action,kind='',ic='plus'){if(state.role==='Leadership'&&['open-daily','session-entry','enter-marks','activity-entry','new-activity','new-visit','new-child','new-morarji','new-guidance'].includes(action))return '';return `<button class="btn ${kind}" data-action="${action}">${icon(ic)}${text}</button>`;}
function metric(label,value,foot,ic='people',tone=''){return `<div class="card metric ${tone}"><div class="metric-top">${label}<span class="metric-icon">${icon(ic)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function bar(label,value,max,tone='green',action=''){return `<div class="bar-row"><${action?'button':'span'} class="${action?'view-link':''}" ${action?`data-centre="${action}"`:''}>${esc(label)}</${action?'button':'span'}><div class="bar-track"><div class="bar-fill" style="width:${max?Math.max(0,Math.min(100,value/max*100)):0}%;background:var(--${tone})"></div></div><span class="bar-value">${value??'—'}</span></div>`;}
function columns(items,{max=null,axis='Students',gender=false}={}){const top=Math.max(1,max??Math.max(...items.map(r=>r.value??0))),w=640,h=250,left=42,right=14,y0=202,plot=168,step=(w-left-right)/items.length,bw=Math.min(52,step*.6);const grid=[0,.25,.5,.75,1].map(f=>{const y=y0-f*plot;return `<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e2e7e1"/><text x="${left-8}" y="${y+4}" text-anchor="end" fill="#647775" font-size="12">${+(top*f).toFixed(1)}</text>`;}).join('');return `<div class="column-chart"><div class="chart-axis-label">${esc(axis)}</div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(axis)}: ${esc(items.map(r=>r.label+' '+(r.value??'not recorded')).join(', '))}">${grid}${items.map((r,i)=>{const x=left+step*(i+.5),height=r.value==null?0:r.value/top*plot;return `<g><title>${esc(r.label)}: ${r.value??'Not recorded'}</title><rect x="${x-bw/2}" y="${y0-height}" width="${bw}" height="${height}" rx="4" fill="var(--${r.tone||'brand'})"/><text x="${x}" y="${y0-height-9}" text-anchor="middle" fill="#203735" font-size="14" font-weight="600">${r.value??'—'}</text><text x="${x}" y="${y0+23}" text-anchor="middle" fill="#536864" font-size="13">${esc(r.label)}</text></g>`;}).join('')}</svg>${gender?`<div class="gender-chart-controls">${['Girl','Boy'].map(g=>`<button class="btn tiny ${state.gender===g?'primary':''}" data-gender="${g}" aria-pressed="${state.gender===g}">${g==='Girl'?'Girls':'Boys'}${state.gender===g?' · clear ×':''}</button>`).join('')}</div>`:''}</div>`;}
function shortColumns(body,title){const template=document.createElement('template');template.innerHTML=body;const bars=[...template.content.children].filter(e=>e.classList.contains('bar-row'));if(!bars.length||bars.length>5)return body;const items=bars.map(row=>{const label=row.firstElementChild,fill=row.querySelector('.bar-fill'),raw=row.querySelector('.bar-value').textContent;return {label:label.textContent,value:raw==='—'?null:Number(raw),tone:fill.style.background.match(/--([\w-]+)/)?.[1]||'brand'};});const controls=bars.map(row=>row.querySelector('button')).filter(Boolean).map(b=>b.outerHTML).join('');bars.forEach(b=>b.remove());const percent=items.some(r=>r.label.includes(' · %')),marks=title==='Average by centre'||title==='Progress across exam rounds';return columns(items,{axis:percent?'Attendance (%)':marks?'Average marks':title==='Visits by officer'?'Visits':'Students',max:percent?100:marks?null:Math.max(4,Math.ceil(Math.max(...items.map(r=>r.value||0))/4)*4)})+ (controls?`<div class="gender-chart-controls">${controls}</div>`:'')+template.innerHTML;}
function cohortColumns(all,years){const groups=years.slice().reverse(),series=[['Training cohort','brand',r=>true],['Took exam','blue',r=>r.took],['Passed','green',r=>r.result==='Passed'],['Pending','amber',r=>r.result==='Pending']],top=Math.max(1,...groups.map(y=>all.filter(r=>r.cohort===y).length)),step=570/Math.max(1,groups.length);return `<div class="column-chart"><div class="chart-axis-label">Children</div><svg viewBox="0 0 640 260" role="img" aria-label="${esc(groups.map(y=>y+': '+series.map(([label,,test])=>label+' '+all.filter(r=>r.cohort===y&&test(r)).length).join(', ')).join('; '))}">${[0,.25,.5,.75,1].map(f=>`<line x1="42" y1="${205-f*165}" x2="625" y2="${205-f*165}" stroke="#e2e7e1"/><text x="34" y="${209-f*165}" text-anchor="end" font-size="12" fill="#647775">${+(top*f).toFixed(1)}</text>`).join('')}${groups.map((y,i)=>{const cx=48+step*(i+.5);return series.map(([label,tone,test],j)=>{const n=all.filter(r=>r.cohort===y&&test(r)).length,x=cx+(j-1.5)*30,h=n/top*165;return `<g><title>${y} · ${label}: ${n}</title><rect x="${x-11}" y="${205-h}" width="22" height="${h}" rx="3" fill="var(--${tone})"/><text x="${x}" y="${197-h}" text-anchor="middle" font-size="13">${n}</text></g>`;}).join('')+`<text x="${cx}" y="232" text-anchor="middle" font-size="13">${esc(y)}</text>`;}).join('')}</svg><div class="gender-chart-controls">${series.map(([label,tone])=>`<span><i style="display:inline-block;width:10px;height:10px;background:var(--${tone});margin-right:5px"></i>${label}</span>`).join('')}</div></div>`;}
const chartNumbers={'overview|Students enrolled by centre': 24, 'overview|Students by grade': 22, 'overview|Students by gender': 23, 'overview|Attendance across centres': 1, 'overview|Participation across centres': 2, 'overview|Engagement across centres': 25, 'attendance|Attendance bands': 3, 'attendance|Attendance by centre': 4, 'attendance|CAC sessions delivered': 5, 'learning|Current exam performance': 6, 'learning|Average by centre': 7, 'learning|Progress across exam rounds': 8, 'learning|Change between exam rounds': 9, 'learning|School performance': 10, 'activities|Participation distribution': 11, 'activities|Participation by centre': 12, 'visits|Visits by officer': 13, 'visits|Centre coverage': 14, 'morarji|Children passing, year on year': 15, 'morarji|Compare the cohort sizes': 16, 'morarji|After the exam': 18, 'guidance|Subject / course chosen': 19, 'donor|Attendance across funded centres': 20, 'donor|Activity participation': 21};
function section(title,sub,body,extra=''){if(state.role==='Teacher'&&['Students enrolled by centre','Average by centre','Attendance by centre','Participation by centre','Engagement across centres'].includes(title))return '';const original=title;if(state.role==='Teacher')title=({'Attendance across centres':'Attendance at your centre','Participation across centres':'Participation at your centre'})[title]||title;if(original==='Progress across exam rounds'){title='Average score by exam round';sub='Mean marks out of the displayed maximum · n = students with scores';}const number=chartNumbers[state.page+'|'+original];body=shortColumns(body,original);return `<section class="card" data-chart="${number||''}"><div class="section-head"><div><h2>${number?`<span class="chart-reference">Chart ${number}</span> `:''}${title}</h2><p>${sub}</p></div>${extra}</div>${body}</section>`;}
function chartCentres(kind){const list=children();const rows=scope().map(c=>{const xs=list.filter(s=>s.centre===c.id),rs=xs.map(stats);let val=0,scale=null;if(kind==='attendance')val=attendanceRate(xs).rate;if(kind==='activities')val=rs.filter(r=>r.coreAct>=2&&!r.coreUnknown).length;if(kind==='score'){const g=scoreGroup(xs);val=g.avg;scale=g.max;}return {c,val,scale};});const max=Math.max(1,...rows.map(r=>r.val??0));return rows.map(r=>bar(r.c.name+(kind==='score'?' / '+(r.scale||'mixed'):kind==='attendance'?' · %':''),r.val,kind==='score'?(r.scale||25):kind==='attendance'?100:max,kind==='score'?'blue':kind==='activities'?'brand':'green',r.c.id)).join('')||empty('No centres match these filters.');}

const empty=t=>`<div class="empty">${icon('info')}<p>${t}</p></div>`;
function engagementCategory(r){return !r.days||r.missing||r.unknown?'Incomplete records':r.good?'Good engagement':r.p<15||r.act<2?'Low engagement':'Review engagement';}
function engagement(r){const category=engagementCategory(r);return !r.days?badge('No attendance period'):badge(category,category==='Good engagement'?'green':category==='Low engagement'?'red':category==='Review engagement'?'blue':'muted');}
function centreEngagement(){const list=children(),categories=[['Good engagement','green'],['Review engagement','blue'],['Low engagement','red'],['Incomplete records','muted']];return section('Engagement across centres','Share of enrolled students in each group · selected month and shifts',`<div class="engagement-legend">${categories.map(([label,tone])=>`<span><i class="legend-dot ${tone}"></i>${label}</span>`).join('')}</div>${scope().map(c=>{const rows=list.filter(s=>s.centre===c.id).map(stats),n=rows.length,counts=categories.map(([label])=>rows.filter(r=>engagementCategory(r)===label).length);return `<div class="engagement-centre"><div class="engagement-centre-head"><button class="name-link" data-centre="${c.id}">${esc(c.name)}</button><span>${n} students</span></div><div class="engagement-stack" role="img" aria-label="${esc(c.name)}: ${categories.map(([label],i)=>`${label} ${counts[i]} of ${n}`).join(', ')}">${categories.map(([label,tone],i)=>counts[i]?`<span class="engagement-segment ${tone}" style="width:${counts[i]/n*100}%" title="${label}: ${counts[i]} of ${n} (${(counts[i]/n*100).toFixed(1)}%)">${(counts[i]/n*100).toFixed(1)}%</span>`:'').join('')}${!n?'<span>No students in this selection</span>':''}</div><p class="chart-note">${['Good','Review','Low','Incomplete'].map((label,i)=>`${label}: ${counts[i]}`).join(' · ')}</p></div>`;}).join('')}<p class="chart-note">All four groups use the same student total per centre. Incomplete or missing attendance periods stay separate. Percentages are rounded; exam scores do not determine engagement. ${state.role==='Leadership'?'Select a centre to compare aggregate results.':'Select a centre, then use the student table below to review individual records.'}</p>`);}
function dataEntryGaps(t){return `<section class="card data-entry-gaps" aria-label="Data entry completeness"><h2>Data entry gaps</h2><div><strong>${t.missing}</strong><span>attendance entries unmarked</span></div><div><strong>${t.rows.filter(r=>r.unknown).length}</strong><span>students with missing activity records</span></div><div><strong>${t.rows.filter(r=>r.score===null).length}</strong><span>${state.exam} scores not recorded</span></div><p>These are different units; they are not added into a single missing-record total. Unmarked is not absent.</p></section>`;}
function summary(){if(state.role==='Leadership')return '';let rows=totals().rows.filter(r=>(!state.query||`${r.s.name} ${r.s.id}`.toLowerCase().includes(state.query.toLowerCase()))&&(!state.concerns||!r.good)&&(!state.engagementFilter||engagementCategory(r)===state.engagementFilter));return `<section class="card table-card"><div class="table-head"><div><h2><span class="chart-reference">Table 1</span> Student performance summary</h2><p>Attendance, participation and learning — together, without combining the scores.</p></div><div class="table-tools"><input class="search" id="student-search" aria-label="Search students" placeholder="Search student or ID" value="${esc(state.query)}"><label class="summary-engagement-filter"><span>Engagement</span><select data-filter="engagementFilter" aria-label="Filter student table by engagement"><option value="">All students</option>${['Good engagement','Review engagement','Low engagement','Incomplete records'].map(v=>`<option ${state.engagementFilter===v?'selected':''}>${v}</option>`).join('')}</select></label></div></div><div class="table-scroll"><table><thead><tr><th class="sticky-name">Student</th><th>Centre / shift</th><th>Attendance</th><th>Activities</th><th>${state.exam} · combined test</th><th>Engagement</th>${state.grade==='10'?'<th>Passed Class 10 board exam?</th>':''}<th>Follow-up</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="sticky-name"><button class="name-link" data-child="${r.s.id}">${esc(r.s.name)}</button><div class="subtext">${r.s.id} · Grade ${r.s.grade} · ${r.s.gender}</div></td><td>${centreName(r.s.centre)}<div class="subtext">${r.s.shift}</div></td><td><strong>${r.p}</strong> days<div class="subtext">${!r.days?'No attendance period':r.missing?`${r.missing} unmarked`:attendanceBand(r.p).label}</div></td><td><strong>${r.act}</strong> / ${r.held} held<div class="subtext">${r.coreAct} cultural/sports · ${r.held?activityBand(r.act,r.unknown).label:'No held activities'}</div></td><td><strong>${r.score??'—'}</strong>${r.score!==null?' / '+r.maxMarks:''}<div class="subtext">${recordedBand(r).label}</div></td><td>${engagement(r)}</td>${state.grade==='10'?`<td>${esc(r.s.boardPassed||'Not entered')}</td>`:''}<td><button class="text-button" data-followup="${r.s.id}">${db.followups[r.s.id]?'View note':'Add note'} →</button></td></tr>`).join('')}</tbody></table>${!rows.length?empty('No students match your selection.'):''}</div><div class="table-footer"><span>${rows.length} children · ${monthName()}</span><span>Green: &gt;20 days AND 2+ cultural/sports activities. Exam score is separate.</span></div></section>`;}
function overview(){const t=totals(),visits=db.visits.filter(v=>v.date.startsWith(state.month)&&scope().some(c=>c.id===v.centre)&&v.status==='Completed').length;return head(state.role==='Cluster Officer'?'Your centres, at a glance':'Programme overview',state.role==='Leadership'?'Programme and centre summaries · no individual records or data entry.':state.role==='Teacher'?'Your centre’s attendance, participation and learning.':'Compare assigned centres, then review students and update records.',state.role==='Leadership'?button('Donor summary','donor','','heart'):state.role==='Teacher'?button('Enter attendance','open-daily','primary','calendar'):button('Record a visit','new-visit','primary','plus'))+filters()+`<div class="grid metrics">${metric('Students enrolled',t.rows.length,`${scope().length} sample centres · selected roster`)}${metric('Students with good engagement',t.good,'>20 attendance days + 2+ activities','activity')}${metric('Students with low attendance',t.low,'Below 15 days · complete records','flag','alert')}${metric('Cluster Officer visits completed',visits,`${scope().length*4} expected · selected month`,'visit')}${metric('Students scoring above 20',t.rows.filter(r=>r.score>20&&r.maxMarks===25).length,`${state.exam} · combined test out of 25`,'book')}${dropoutCard()}</div>${state.role==='Teacher'?'':`<div class="enrolment-first compact-centre-chart">${section('Students enrolled by centre','Student count · selected month and shifts',scope().map(c=>bar(c.name,t.rows.filter(r=>r.s.centre===c.id).length,t.rows.length,'brand',c.id)).join(''))}</div>`}${profileBreakdown()}<div class="grid two-col">${section('Attendance across centres','Monthly attendance % · selected centres',chartCentres('attendance'))}${section('Participation across centres','Students attending 2+ cultural/sports activities · monthly',chartCentres('activities'))}</div>${centreEngagement()}${morarjiScorecard()}`+summary()+`<details class="definitions-details"><summary>How these numbers are calculated</summary>${reviewNotes()}</details>`;}
function sessionPanel(){const all=db.sessions.filter(r=>scope().some(c=>c.id===r.centre)&&r.date.startsWith(state.month)&&(!state.shift||r.shift===state.shift));return section('CAC sessions delivered','Centre × shift × date · separate from child attendance',columns([{label:'Planned total',value:all.length,tone:'blue'},{label:'Held',value:all.filter(r=>r.status==='Held').length,tone:'green'},{label:'Cancelled',value:all.filter(r=>r.status==='Cancelled').length,tone:'orange'}],{axis:'Centre-shift sessions'})+`<p class="chart-note">${all.filter(r=>r.status==='Planned').length} sessions awaiting delivery. Planned count includes held and cancelled sessions in the original plan. Sample operating calendar only.</p>`,button('Update session','session-entry','','calendar'));}
function attendance(){const t=totals(),bands=[['Below 15',r=>r.p<15,'red'],['15 days',r=>r.p===15,'amber'],['16–20',r=>r.p>=16&&r.p<=20,'blue'],['21–25',r=>r.p>20,'green']];return head('Attendance','Find low attendance, review missing records, and follow up with children.',button('Enter attendance','open-daily','primary','calendar'))+filters()+`<div class="grid metrics">${metric('Student attendance rate',attendanceRate(children()).label,'Present / eligible held-session student-days','calendar')}${metric('Students with low attendance',t.low,'Below 15 days · complete records','flag','alert')}${metric('Attendance entries not marked',t.missing,'Not counted as absent','info')}</div><div class="grid two-col">${section('Attendance bands','Child counts · only complete monthly records',bands.map(([l,f,c])=>bar(l,t.rows.filter(r=>r.days>0&&!r.missing&&f(r)).length,t.rows.length,c)).join('')+`<p class="chart-note">${t.rows.filter(r=>r.missing).length} children excluded from bands because attendance is incomplete. October bands describe month-to-date counts.</p>`)}${section('Attendance by centre','Monthly attendance % · select a centre to review',chartCentres('attendance'))}</div>`+sessionPanel()+attendanceTable();}
function daily(){const list=children(),marked=list.filter(s=>db.attendance[s.id+'|'+state.date]).length;return head('Daily Attendance',`${state.role==='Teacher'?'Aralimatti CAC':'Record attendance'} · mark every child, in either shift. Corrections save immediately.`,button('Monthly insights','monthly-attendance','','chart'))+`<div class="filters">${state.role!=='Teacher'?select('Centre','centre',scope().map(c=>[c.id,c.name]),'All assigned centres'):''}<span class="filter-note">P = Present · A = Absent · H = Holiday</span></div><div class="attendance-layout"><section class="card table-card"><div class="table-head attendance-header"><div class="date-bar"><button class="btn tiny" data-action="prev-date" aria-label="Previous day">←</button><input type="date" id="attendance-date" aria-label="Attendance date" value="${state.date}" max="${TODAY}"><button class="btn tiny" data-action="next-date" ${state.date>=TODAY?'disabled':''} aria-label="Next day">→</button></div><div class="pill-group">${['','Morning','Evening'].map(v=>`<button data-shift="${v}" class="${state.shift===v?'active':''}">${v||'Both shifts'}</button>`).join('')}</div></div><div class="mobile-only" style="padding:0 17px 10px">${button('Update session','session-entry','tiny','calendar')}</div><div class="roster-header"><span>${marked} / ${list.length} saved · new entries default to P</span>${button('Save attendance','save-default-attendance','primary','check')}<div><button class="text-button" data-action="mark-all">Mark all present</button><button class="text-button" data-action="mark-all-absent">Mark all absent</button></div></div><div class="progress"><i style="width:${list.length?marked/list.length*100:0}%"></i></div>${list.map(s=>{const saved=db.attendance[s.id+'|'+state.date],v=saved||'P';return `<div class="student-row"><div class="avatar">${s.name.slice(0,1)}</div><div style="flex:1"><button class="name-link" data-child="${s.id}">${esc(s.name)}</button><div class="subtext">Grade ${s.grade} · ${s.shift} · ${state.role!=='Teacher'?centreName(s.centre):s.id}</div></div><div class="mark-buttons" role="group" aria-label="Attendance for ${esc(s.name)}">${['P','A','H'].map(c=>`<button data-mark="${s.id}|${c}" aria-label="${esc(s.name)} ${c==='P'?'Present':c==='A'?'Absent':'Holiday'}" aria-pressed="${v===c}" class="${v===c?'sel-'+c:''}">${c}</button>`).join('')}</div><span class="save-indicator">${saved?icon('check'):'Draft P'}</span></div>`;}).join('')||empty('No children in this selection.')}</section><aside class="attendance-aside">${section('Saved as you mark','One record per child and date',`<div class="key"><span class="badge green">P</span> Present</div><div class="key"><span class="badge red">A</span> Absent</div><div class="key"><span class="badge muted">H</span> Holiday</div><p class="chart-note">Tap a different code to correct an entry. New entries show Present as an unsaved draft. Save attendance confirms those entries; existing A/H records are preserved. Holiday entries are excluded from attendance-day denominators.</p>${button('See monthly attendance','monthly-attendance','','chart')}${button('Update session status','session-entry','','calendar')}`)}${section('A holiday for this group?',fmtDate(state.date),`<p class="chart-note">This changes only the children currently shown.</p>${button('Mark group holiday','mark-holiday','','calendar')}`)}</aside></div>`;}
function learning(){const list=children(),scored=list.map(s=>stats(s)).filter(r=>r.score!==null),group=scoreGroup(list),avg=group.avg??'—';const matched=list.filter(s=>state.fromExam!==state.toExam&&db.scores[s.id]?.[state.fromExam]!=null&&db.scores[s.id]?.[state.toExam]!=null&&scoreInfo(s,state.fromExam).maxMarks===scoreInfo(s,state.toExam).maxMarks),change=matched.length&&new Set(matched.map(c=>scoreInfo(c,state.fromExam).maxMarks)).size===1?(matched.reduce((n,s)=>n+db.scores[s.id][state.toExam]-db.scores[s.id][state.fromExam],0)/matched.length).toFixed(1):'—';const sameScale=matched.length>0&&new Set(matched.map(c=>scoreInfo(c,state.fromExam).maxMarks)).size===1,earlier=sameScale?matched.reduce((n,c)=>n+db.scores[c.id][state.fromExam],0)/matched.length:null,later=sameScale?matched.reduce((n,c)=>n+db.scores[c.id][state.toExam],0)/matched.length:null,growth=earlier>0?(later-earlier)/earlier*100:null;return head('Learning',state.role==='Leadership'?'Review combined-test performance and matched-student changes.':'Review one combined CAC test per exam round. Enter or correct marks here.',button('Enter marks','enter-marks','primary','plus'))+filters()+`<div class="notice neutral">${icon('info')}<p><strong>Combined test only.</strong> F1–F4 are separate exam rounds. Use the group exam date and configured maximum marks. Add any assessment comment once for the group. Existing sample records use 25 marks. Other scales remain unbanded until their boundaries are agreed.</p></div><div class="comparison-controls">${select('Compare rounds','comparison',[['F1|F2','F1 → F2'],['F2|F3','F2 → F3'],['F3|F4','F3 → F4'],['F1|F4','F1 → F4']],null)}</div><p class="chart-note comparison-definition">Percentage improvement = (later average − earlier average) ÷ earlier average × 100, for the same matched students and scoring scale. It is not the percentage of students who improved. A zero baseline has no defined percentage; confirm paper comparability before interpreting change.</p><div class="grid metrics">${metric('Students with exam scores recorded',`${scored.length}<span class="unit"> / ${list.length}</span>`,`${state.exam} · selected children`,'book')}${metric('Average student exam score',avg,group.max?'Combined test · out of '+group.max:'Different scales · filter before averaging','chart')}${metric('Students without an exam score',list.length-scored.length,'Missing is not a zero score','info')}${metric('Average score improvement',growth===null?'—':`${growth>0?'+':''}${growth.toFixed(1)}%`,`${state.fromExam} → ${state.toExam} · ${matched.length} matched students · ${earlier===null?'same scoring scale required':earlier===0?'zero baseline: percentage undefined':earlier.toFixed(1)+' → '+later.toFixed(1)+' marks'}`,'chart')}</div><div class="grid two-col">${section('Current exam performance',`${state.exam} · 25-mark records only · other scales unbanded`,[['0–8','red',n=>n<=8],['9–15','amber',n=>n>=9&&n<=15],['16–20','blue',n=>n>=16&&n<=20],['21–25','green',n=>n>=21]].map(([l,c,f])=>bar(l,scored.filter(r=>r.maxMarks===25&&f(r.score)).length,list.length,c)).join(''))}${section('Average by centre',`${state.exam} · excludes unrecorded scores`,chartCentres('score'))}</div><div class="grid two-col">${section('Progress across exam rounds','Selected children · averages and result coverage', ['F1','F2','F3','F4'].map(ex=>{const g=scoreGroup(list,ex);return bar(`${ex} / ${g.max||'mixed'} · n=${g.n}`,g.avg,g.max||25,'blue');}).join('')+`<p class="chart-note">Round averages may include different children. The matched comparison uses the selected rounds and equal recorded maximum marks. Equal maxima alone do not prove paper comparability.</p>`)}${comparisonPanel(matched)}${section('School performance','A future comparison, once school reports are received',`<div class="notice neutral"><p>School reports have not been loaded. Confirm reporting periods, matched students and scoring scales before showing improved / unchanged / declined results. No school-performance improvement or CAC impact is inferred from these sample CAC scores.</p></div>`)}</div>`+learningTable();}
function activityEvents(){return db.events.filter(e=>scope().some(c=>c.id===e.centre)&&e.date.startsWith(state.month)&&(!state.shift||!e.shift||e.shift==='Both shifts'||e.shift===state.shift));}
function activities(){const t=totals(),ev=activityEvents(),selectedCentre=state.centre||scope()[0]?.id,shown=ev.filter(e=>e.centre===selectedCentre).sort((a,b)=>a.date.localeCompare(b.date));return head('Activities & engagement',state.role==='Leadership'?'Review activity delivery and student participation across centres.':'Record participation, spot low engagement, and review it alongside attendance.',button('Record participation','activity-entry','primary','plus')+button('Add session','new-activity','','activity'))+filters()+`<div class="grid metrics">${metric('Activity sessions held / planned',`${ev.filter(e=>e.status==='Held').length} / ${ev.length}`,`${ev.filter(e=>e.status==='Planned').length} awaiting delivery · ${ev.filter(e=>e.status==='Cancelled').length} cancelled · centre-events`,'activity')}${metric('Students attending 2+ activities',t.rows.filter(r=>r.coreAct>=2&&!r.unknown).length,'Monthly participation · not an award','people')}${metric('Students with good engagement',t.good,'>20 present days + 2+ activities','check')}${metric('Students with activity records missing',t.rows.filter(r=>r.unknown).length,'Children with unrecorded participation','info')}</div>${state.role==='Leadership'?'':`<div class="section-head"><div><h2>Four Saturdays, four opportunities</h2><p>${centreName(selectedCentre)} · ${monthName()} · 1st & 3rd cultural, 2nd & 4th sports</p></div>${scope().length>1?badge('First selected centre shown'):''}</div><div class="event-grid">${shown.map(e=>`<article class="card event-card"><div class="event-date">${fmtDate(e.date).replace(' 2026','')} ${badge(e.status,e.status==='Held'?'green':'muted')}</div><div class="event-icon">${icon(e.category==='Cultural'?'activity':'flag')}</div><strong>${esc(e.name)}</strong><p>${e.category}</p><button class="btn tiny" data-event="${e.id}">View / update</button></article>`).join('')}</div>`}<div class="grid two-col" style="margin-top:22px">${section('Participation distribution','Each child counted once; below 2 is a provisional low-participation flag',Array.from({length:5},(_,i)=>bar(`${i===4?'4+':i} ${i===1?'activity':'activities'}`,t.rows.filter(r=>r.held>0&&(i===4?r.act>=4:r.act===i)&&!r.unknown).length,t.rows.filter(r=>r.held>0).length,i<2?'orange':'green')).join(''))}${section('Participation by centre','Students attending 2+ cultural/sports activities',chartCentres('activities'))}</div><div class="notice neutral" style="margin-bottom:22px">${icon('check')}<p><strong>Green = good engagement.</strong> More than 20 attendance days and at least two activities, with complete records. Exam marks remain separate. Important days are tracked separately; whether they count towards engagement needs confirmation. The prototype uses cultural/sports participation for green engagement.</p></div>`+(state.role==='Leadership'?'':activityPlanReference());}
function dropoutStatus(student){return cacDropout(student,state.month,TODAY,db.sessions,db.attendance);}
function dropoutCard(){const rows=children().map(dropoutStatus),complete=rows.filter(r=>r.assessed),count=rows.filter(r=>r.dropout).length;return metric('Students classified as CAC dropout',complete.length?count:'—',rows.length&&rows.every(r=>r.reason==='Month not complete')?`${monthName()} · month not complete`:`${monthName()} · ${complete.length} assessed · ${rows.length-complete.length} not classified`,'flag',count?'alert':'');}

function attendanceRate(list){if(liveReview){let p=0,eligible=0;for(const student of list){const days=globalThis.__massReviewObservedDatesByCentre?.[student.centre]?.[state.month]||[];for(const date of days){const code=db.attendance[student.id+'|'+date];if(!['P','A','L'].includes(code))continue;eligible++;if(code==='P')p++;}}const rate=eligible?+(100*p/eligible).toFixed(1):null;return {p,eligible,missing:0,rate,label:rate===null?'—':rate+'%'};}let p=0,eligible=0,missing=0;for(const student of list){const dates=[...new Set(db.sessions.filter(r=>r.centre===student.centre&&r.shift===student.shift&&r.status==='Held'&&r.date.startsWith(state.month)&&r.date>=student.enrolled&&r.date<=TODAY).map(r=>r.date))];for(const date of dates){const code=db.attendance[student.id+'|'+date];if(code==='H')continue;eligible++;if(code==='P')p++;if(!code)missing++;}}const rate=eligible?+(100*p/eligible).toFixed(1):null;return {p,eligible,missing,rate,label:rate===null?'—':rate+'%'};}
function reviewNotes(){const a=attendanceRate(children());return section('Definitions to confirm','Keep decisions separate from recorded results',`<p class="chart-note"><strong>Attendance:</strong> ${a.label} = ${a.p} present / ${a.eligible} eligible student-days in recorded held sessions; holidays and dates before enrolment excluded. ${a.missing} unmarked entries remain in the denominator and are shown as missing, not absence. This is a first-cut calculation for PM review.</p><p class="chart-note"><strong>CAC dropout:</strong> zero attendance for one full completed calendar month, with sessions held and complete attendance records. In-progress months, incomplete calendars/attendance and students who joined during the month are not classified. Holidays are not absences. This is CAC dropout, not school dropout; the roster is not automatically changed. A rate denominator has not been agreed.</p><p class="chart-note"><strong>Enrolled students</strong> uses the roster’s active enrolment status, independent of attendance. Green engagement = more than 20 present days and at least two cultural/sports activities, with complete records. This does not confer an award.</p>`);}
function topPerformers(){const rows=totals().rows.filter(r=>r.good&&r.coreAct>=4);return section('Strong participation','Students with good engagement and all four cultural/sports activities recorded · not an award ranking',`<div class="attention-list">${rows.map(r=>`<div class="attention-item"><div><button class="name-link" data-child="${r.s.id}">${esc(r.s.name)}</button><p>${centreName(r.s.centre)} · ${r.p} present days · ${r.coreAct} activities · ${state.exam}: ${r.score??'Not entered'}${r.score!==null?' / '+r.maxMarks:''}</p></div>${badge('Good engagement','green')}</div>`).join('')||empty('No complete records meet these display criteria.')}</div><p class="chart-note">Final top-performer criteria need confirmation. Exam marks are shown separately and are not included in this selection.</p>`);}
function profileTable(){if(state.role==='Leadership')return '';const list=db.students.filter(s=>scope().some(c=>c.id===s.centre)&&(!state.shift||s.shift===state.shift)).filter(s=>!state.query||`${s.name} ${s.id}`.toLowerCase().includes(state.query.toLowerCase()));return section('Student Profile','Add and correct student details here; all programme sections use the same ID.',`<input class="search" id="student-search" aria-label="Search students" placeholder="Search student or ID" value="${esc(state.query)}"><div class="table-scroll"><table><thead><tr><th>Student / ID</th><th>Centre</th><th>Grade</th><th>Gender</th><th>Shift</th><th>Enrolled</th><th>Enrolment status</th><th>Exit date</th><th>Class 10 board exam passed?</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><button class="name-link" data-child="${s.id}">${esc(s.name)}</button><div class="subtext">${s.id}</div></td><td>${centreName(s.centre)}</td><td>${s.grade}</td><td>${s.gender}</td><td>${s.shift}</td><td>${fmtDate(s.enrolled)}</td><td>${esc(s.enrolmentStatus||(s.active?'Active':'Left programme'))}</td><td>${s.exitDate?fmtDate(s.exitDate):'—'}</td><td>${s.grade==='10'?esc(s.boardPassed||'Not entered'):'—'}</td><td><button class="text-button" data-edit-child="${s.id}">Edit profile</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':empty('No students match these filters.')}`);}
function attendanceTable(){if(state.role==='Leadership')return '';return section('Student attendance','Selected reporting month · review a student or add a follow-up',`<div class="table-scroll"><table><thead><tr><th>Student</th><th>Centre / shift</th><th>Present days</th><th>Unmarked</th><th>Attendance band</th><th>CAC monthly status</th><th>Follow-up</th></tr></thead><tbody>${totals().rows.map(r=>`<tr><td><button class="name-link" data-child="${r.s.id}">${esc(r.s.name)}</button></td><td>${centreName(r.s.centre)} · ${r.s.shift}</td><td>${r.p}</td><td>${r.missing}</td><td>${badge(r.missing?'Incomplete records':attendanceBand(r.p).label,r.missing?'muted':attendanceBand(r.p).tone)}</td><td>${badge(dropoutStatus(r.s).status,dropoutStatus(r.s).tone)}<div class="subtext">${esc(dropoutStatus(r.s).reason)}</div></td><td><button class="text-button" data-followup="${r.s.id}">Follow up →</button></td></tr>`).join('')}</tbody></table></div>`);}
function learningTable(){if(state.role==='Leadership')return '';return section('Student exam results','All four rounds · edit marks and exam notes without leaving Learning',`<div class="table-scroll"><table><thead><tr><th>Student</th><th>Centre / shift</th>${['F1','F2','F3','F4'].map(ex=>`<th>${ex}</th>`).join('')}<th></th></tr></thead><tbody>${children().map(s=>`<tr><td><button class="name-link" data-child="${s.id}">${esc(s.name)}</button><div class="subtext">${s.id} · Grade ${s.grade}</div></td><td>${centreName(s.centre)} · ${s.shift}</td>${['F1','F2','F3','F4'].map(ex=>{const r=scoreInfo(s,ex);return `<td>${r.score===null?esc(r.status):`${r.score} / ${r.maxMarks}`}</td>`;}).join('')}<td><button class="text-button" data-edit-marks="${s.id}">Edit marks</button></td></tr>`).join('')}</tbody></table></div>`);}
function comparisonPanel(matched){const counts={Improved:0,Unchanged:0,Declined:0};for(const student of matched){const delta=db.scores[student.id][state.toExam]-db.scores[student.id][state.fromExam];counts[delta>0?'Improved':delta<0?'Declined':'Unchanged']++;}return section('Change between exam rounds',`${state.fromExam} → ${state.toExam} · ${matched.length} matched students with the same maximum marks`,state.fromExam===state.toExam?'<p>Select two different exam rounds to compare.</p>':columns(Object.entries(counts).map(([label,value])=>({label,value,tone:label==='Improved'?'green':label==='Declined'?'red':'amber'})),{axis:'Matched students'})+'<p class="chart-note">Raw score difference only; paper comparability must be confirmed. Missing scores are excluded, not counted as unchanged. No effect of CAC participation is inferred.</p>');}
function editLearningRow(id){const student=children().find(s=>s.id===id);if(!student)return;modal('Edit exam marks',student.name+' · '+centreName(student.centre),`<p class="form-help">Student details stay in Student Profile. Maximum marks use configured paper settings. Dates are required for recorded results.</p><div class="table-scroll"><table><thead><tr><th>Round</th><th>Status</th><th>Marks</th><th>Maximum</th><th>Exam date</th></tr></thead><tbody>${['F1','F2','F3','F4'].map(ex=>{const r=scoreInfo(student,ex);return `<tr><td>${ex}</td><td>${drop(ex+' status','status_'+ex,['Recorded','Absent','Not entered'],r.status)}</td><td>${field(ex+' marks','score_'+ex,r.score??'','number')}</td><td>${r.maxMarks}${r.sample?' (sample)':''}</td><td>${field(ex+' date','date_'+ex,r.date,'date')}</td></tr>`;}).join('')}</tbody></table></div>`,f=>{const updates=[];for(const ex of ['F1','F2','F3','F4']){const old=scoreInfo(student,ex),v=f['score_'+ex],status=f['status_'+ex],date=f['date_'+ex],note=old.performance;const changed=v!==(old.score===null?'':String(old.score))||status!==old.status||date!==old.date||note!==old.performance;if(!changed)continue;if(status==='Recorded'&&(v===''||!Number.isInteger(+v)||+v<0||+v>old.maxMarks))throw Error(ex+': enter whole marks from 0 to '+old.maxMarks+'.');if(status!=='Recorded'&&v!=='')throw Error(ex+': clear marks for absent or not entered results.');if(status==='Recorded'&&!date)throw Error(ex+': enter the exam date.');if(date>TODAY)throw Error(ex+': exam date cannot be in the future.');updates.push({ex,score:status==='Recorded'?+v:null,meta:{...db.assessmentDetails[id+'|'+ex],maxMarks:old.maxMarks,status,date,performance:note,year:'2026–27'}});}for(const u of updates){db.scores[id]??={};db.scores[id][u.ex]=u.score;db.assessmentDetails[id+'|'+u.ex]=u.meta;}persist('Exam results saved · charts updated');},true,'Save marks');}
function newMorarji(){const students=db.students.filter(s=>scope().some(c=>c.id===s.centre)&&s.grade==='5'&&!db.morarji[s.id]);modal('Add to Morarji training cohort','Choose an existing student. Add new student profiles in Student Profile.',students.length?`<div class="form-grid">${drop('Student','student',students.map(s=>[s.id,s.name+' · '+centreName(s.centre)]),students[0].id,'full')}${field('Cohort year','cohort',state.morarjiYear,'text','full')}</div>`:empty('No eligible unlinked Grade 5 students. Add or review profiles in Student Profile first.'),students.length?f=>{if(!students.some(s=>s.id===f.student)||!f.cohort.trim())throw Error('Choose a student and cohort year.');db.morarji[f.student]={cohort:f.cohort.trim(),trainingDays:null,applied:null,took:null,result:'Pending',selected:null,admitted:null,scholarship:'Not recorded'};state.morarjiYear=f.cohort.trim();persist('Training cohort record added · outcomes pending');}:null);}
function newGuidance(){modal('Add career-guidance participant','Record an existing participant; this does not create a new student profile.',`<div class="form-grid">${field('Participant name','name','','text','full')}${drop('Centre','centre',scope().map(c=>[c.id,c.name]),scope()[0]?.id)}${drop('Grade','grade',['10','11','12'],'10')}</div><p class="form-help">January 2026 demonstration cohort only. Programme grades and real session records need confirmation.</p>`,f=>{if(!f.name.trim()||!scope().some(c=>c.id===f.centre))throw Error('Enter a participant and assigned centre.');db.guidance.push({id:'G-'+Date.now(),name:f.name.trim(),centre:f.centre,grade:f.grade,contact:'Not contacted',destination:'Unknown',verification:'Self-reported',followup:''});persist('Participant added · next step unknown');});}

let tablePages={};
function paginateTables(root){root.querySelectorAll('table').forEach((table,index)=>{if(table.dataset.paged)return;table.dataset.paged='yes';const rows=[...table.tBodies].flatMap(b=>[...b.rows]);if(rows.length<=10)return;const key=state.page+'|'+(root.id||'root')+'|'+index+'|'+state.centre+'|'+state.shift;let page=Math.min(tablePages[key]||0,Math.ceil(rows.length/10)-1);const controls=document.createElement('div');controls.className='pagination';const show=()=>{rows.forEach((r,i)=>r.hidden=i<page*10||i>=(page+1)*10);controls.innerHTML=`<span>${page*10+1}–${Math.min(rows.length,(page+1)*10)} of ${rows.length}</span><div><button type="button" class="btn tiny" data-pager="previous" ${page===0?'disabled':''}>Previous</button><span> Page ${page+1} of ${Math.ceil(rows.length/10)} </span><button type="button" class="btn tiny" data-pager="next" ${page+1>=Math.ceil(rows.length/10)?'disabled':''}>Next</button></div>`;};controls.addEventListener('click',e=>{const b=e.target.closest('[data-pager]');if(!b||b.disabled)return;page+=b.dataset.pager==='next'?1:-1;tablePages[key]=page;show();});table.closest('.table-scroll')?.after(controls);show();});}
function profileBreakdown(){const list=children(true);return `<div class="grid demographics-grid">${section('Students by grade','Enrolled student count by grade · selected centres and shifts',columns(Array.from({length:10},(_,i)=>({label:String(i+1),value:children().filter(s=>s.grade===String(i+1)).length})),{axis:'Students · Grade 1–10'}))}${section('Students by gender','Select Girls or Boys to filter overview summaries. Select again to clear.',columns(['Girl','Boy'].map(g=>({label:g==='Girl'?'Girls':'Boys',value:list.filter(s=>s.gender===g).length})),{axis:'Students',gender:true}))}</div>`;}

function activitySession(id,draft){const existing=id?db.events.find(e=>e.id===id):null,e=draft||existing||{centre:state.centre||scope()[0]?.id,shift:state.shift||'Both shifts',date:TODAY,name:'Folk dance & song',status:'Held'},names=[...new Set([...activityCatalogue.map(a=>a[0]),...(existing?[existing.name]:[])])];modal(id?'Edit activity session':'Add activity session','Step 1 of 2 · session details',`<div class="form-grid">${drop('Centre','centre',scope().map(c=>[c.id,c.name]),e.centre)}${drop('Shift','shift',['Both shifts','Morning','Evening'],e.shift||'Both shifts')}${field('Session date','date',e.date,'date')}${drop('Activity','name',names,e.name)}${drop('Session status','status',['Held','Planned','Cancelled'],e.status)}</div><p class="form-help">This is the sample activity catalogue. MASS must confirm its standard activity list. CAC daily attendance and activity participation remain separate records.</p>`,f=>{if(!scope().some(c=>c.id===f.centre)||!f.date)throw Error('Choose an assigned centre and session date.');if(f.status==='Held'&&f.date>TODAY)throw Error('Future sessions must remain planned.');const category=activityCatalogue.find(a=>a[0]===f.name)?.[1]||existing?.category;if(!category)throw Error('Choose a listed activity.');activityParticipants(id,{...f,category});return false;},false,'Next: mark participation');}
function participationButtons(s,value){return `<input type="hidden" name="p_${s.id}" value="${esc(value)}"><div class="mark-buttons" role="group" aria-label="Participation for ${esc(s.name)}">${[['Attended','P'],['Not attended','A']].map(([v,l])=>`<button type="button" data-participation="${s.id}" data-value="${v}" aria-label="${esc(s.name)} ${v}" aria-pressed="${value===v}" class="${value===v?'sel-'+l:''}">${l}</button>`).join('')}<span class="participation-state">${value||'Unmarked'}</span></div>`;}
function activityParticipants(id,event){const ids=scope().map(c=>c.id),list=db.students.filter(s=>ids.includes(s.centre)&&s.centre===event.centre&&(event.shift==='Both shifts'||s.shift===event.shift)&&s.enrolled<=event.date&&(!s.exitDate||s.exitDate>=event.date)),values=Object.fromEntries(list.map(s=>[s.id,db.participation[s.id+'|'+id]||'']));modal('Session participation','Step 2 of 2 · '+event.name+' · '+centreName(event.centre)+' · '+event.shift+' · '+fmtDate(event.date),`<p class="form-help">P = participated · A = did not participate. No one is marked present by default. Tap a selected code to clear it. Mark all students before saving a held session.</p><div class="bulk-actions"><button type="button" class="btn tiny" data-participation-all="Attended">Mark all present</button><button type="button" class="btn tiny" data-participation-all="Not attended">Mark all absent</button></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Grade / shift</th><th>Participation</th></tr></thead><tbody>${list.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.grade} · ${s.shift}</td><td>${participationButtons(s,['Attended','Not attended'].includes(values[s.id])?values[s.id]:'')}</td></tr>`).join('')}</tbody></table></div>`,f=>{if(!list.length&&event.status==='Held')throw Error('No eligible students in this group. Review session details.');if(event.status==='Held'&&list.some(s=>!['Attended','Not attended'].includes(f['p_'+s.id])))throw Error('Mark participation for every student before saving the held session.');if(event.status!=='Held'&&list.some(s=>f['p_'+s.id]))throw Error('Planned or cancelled sessions cannot have participation. Clear entries or mark the session held.');if(db.events.some(e=>e.id!==id&&e.centre===event.centre&&e.date===event.date&&(e.shift||'Both shifts')===event.shift&&e.name===event.name))throw Error('This session already exists. Open its record instead.');const eventId=id||'EV-'+Date.now();if(id)Object.assign(db.events.find(e=>e.id===id),event);else db.events.push({id:eventId,...event});for(const key of Object.keys(db.participation))if(key.endsWith('|'+eventId)&&!list.some(s=>key===s.id+'|'+eventId))delete db.participation[key];for(const s of list){const key=s.id+'|'+eventId;if(f['p_'+s.id])db.participation[key]=f['p_'+s.id];else delete db.participation[key];}state.month=event.date.slice(0,7);persist('Session and participation saved together');},true,'Save session & participation');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-participation],[data-participation-all]');if(!b)return;const form=b.closest('form');const set=(input,value)=>{input.value=value;const box=input.nextElementSibling;box.querySelectorAll('button').forEach(button=>{const selected=button.dataset.value===value;button.setAttribute('aria-pressed',selected);button.className=selected?'sel-'+(value==='Attended'?'P':'A'):'';});box.querySelector('.participation-state').textContent=value||'Unmarked';};if(b.dataset.participationAll)form.querySelectorAll('input[name^="p_"]').forEach(input=>set(input,b.dataset.participationAll));else{const input=form.querySelector('[name="p_'+b.dataset.participation+'"]');set(input,input.value===b.dataset.value?'':b.dataset.value);}});

function roster(){return head('Student Profile','Maintain the centre roster, then use the same records for attendance and learning.',button('Add student','new-child','primary','plus'))+filters()+profileTable();}
function visits(){const cs=scope(),vis=db.visits.filter(v=>cs.some(c=>c.id===v.centre)&&v.date.startsWith(state.month)),completed=vis.filter(v=>v.status==='Completed');return head(state.role==='Leadership'?'Officer visits':'Visits to your centres','Check monthly coverage: four visits per centre, two for each shift.',button('Record a visit','new-visit','primary','plus'))+filters({simple:true})+`<div class="grid metrics">${metric('Cluster Officer visits completed / planned',`${completed.length} / ${cs.length*4}`,'Reported four-visit monthly plan · selected centres','visit')}${metric('Morning-shift visits completed',completed.filter(v=>v.shift==='Morning').length,`${cs.length*2} expected`,'clock')}${metric('Evening-shift visits completed',completed.filter(v=>v.shift==='Evening').length,`${cs.length*2} expected`,'clock')}${metric('Centres meeting the visit target',cs.filter(c=>['Morning','Evening'].every(sh=>completed.filter(v=>v.centre===c.id&&v.shift===sh).length>=2)).length,`Out of ${cs.length} selected centres`,'check')}</div><div class="grid two-col">${section('Visits by officer','Completed visits / expected visits for assigned centres',['Meera','Kavya'].filter(o=>cs.some(c=>c.officer===o)).map(o=>bar(`${o} / ${cs.filter(c=>c.officer===o).length*4}`,completed.filter(v=>v.officer===o).length,cs.filter(c=>c.officer===o).length*4,'green')).join(''))}${section('Centre coverage','Morning / evening visit counts',cs.map(c=>{const m=completed.filter(v=>v.centre===c.id&&v.shift==='Morning').length,e=completed.filter(v=>v.centre===c.id&&v.shift==='Evening').length;return `<div class="rule-row"><button class="name-link" data-centre="${c.id}">${c.name}</button><span>${m} morning · ${e} evening</span>${badge(m>=2&&e>=2?'Covered':'Visit gap',m>=2&&e>=2?'green':'amber')}</div>`;}).join(''))}</div>${state.role==='Leadership'?'':`<section class="card table-card"><div class="table-head"><div><h2>Visit log</h2><p>Attendance review, centre feedback and next action</p></div></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Officer</th><th>Centre / shift</th><th>Feedback</th><th>Next action</th><th>Status</th></tr></thead><tbody>${vis.sort((a,b)=>b.date.localeCompare(a.date)).map(v=>`<tr><td>${fmtDate(v.date)}</td><td>${esc(v.officer)}</td><td>${centreName(v.centre)}<div class="subtext">${v.shift}</div></td><td>${esc(v.feedback)}</td><td>${esc(v.action)}</td><td>${badge(v.status,'green')}</td></tr>`).join('')}</tbody></table>${!vis.length?empty('No visits recorded for this month.'):''}</div></section>`}`;}
function morarjiRows(ignoreDonor=false){const ids=centres.filter(c=>(state.role!=='Teacher'||c.id==='C01')&&(state.role!=='Cluster Officer'||c.officer==='Meera')&&(!state.centre||c.id===state.centre)&&(!state.officer||c.officer===state.officer)&&(ignoreDonor||!state.donor||c.donor===state.donor)).map(c=>c.id);return [...Object.entries(db.morarji).map(([id,r])=>({s:db.students.find(s=>s.id===id),...r})),...db.morarjiHistory].filter(r=>r.s&&ids.includes(r.s.centre));}
function morarjiYears(){return [...new Set(morarjiRows(true).map(r=>r.cohort))].sort().reverse();}
function morarjiScorecard(){const rows=morarjiRows().filter(r=>r.cohort===state.morarjiYear),passed=rows.filter(r=>r.result==='Passed').length;return `<section class="card morarji-scorecard" style="margin-bottom:22px"><div class="section-head"><div><h2>Morarji entrance exam</h2><p>Cohort results · selected centres${state.donor?' and donor':''} · independent of CAC reporting month, grade, gender and shift</p></div>${select('Cohort year','morarjiYear',morarjiYears(),null)}</div><div class="morarji-headline"><div><strong>${passed}</strong><span>children passed</span></div><div><strong>${rows.filter(r=>r.took).length}</strong><span>took the exam</span></div><div><strong>${rows.filter(r=>r.result==='Pending').length}</strong><span>results pending</span></div></div><p class="chart-note">${esc(state.morarjiYear)} · fictional sample cohort. Passing does not imply scholarship receipt.</p>${state.page!=='donor'?button('Review Morarji','open-morarji','','arrow'):''}</section>`;}
function morarji(){const all=morarjiRows(true),rows=all.filter(r=>r.cohort===state.morarjiYear),years=morarjiYears(),max=Math.max(1,...years.map(y=>all.filter(r=>r.cohort===y&&r.result==='Passed').length));const availableCentres=centres.filter(c=>(state.role!=='Teacher'||c.id==='C01')&&(state.role!=='Cluster Officer'||c.officer==='Meera'));return head('Morarji scholarship prep','Compare yearly entrance-exam results, then review the selected cohort’s follow-up.',button('Add to training cohort','new-morarji','primary','plus'))+`<div class="filters">${select('Cohort year','morarjiYear',years,null)}${state.role!=='Teacher'?select('Centre','centre',availableCentres.map(c=>[c.id,c.name]),'All centres'):''}<button class="reset-filter" data-action="reset-morarji">Reset filters</button></div><div class="notice neutral" style="margin-bottom:22px">${icon('info')}<p><strong>Fictional sample cohorts: 2024–25 and 2025–26.</strong> Year refers to the preparation/exam cohort. Weekend preparation runs August–February. Actual year labels and historical data coverage need confirmation.</p></div><div class="grid two-col">${section('Children passing, year on year','Number of children with a recorded pass result · same centre scope',years.slice().reverse().map(y=>`<div class="bar-row"><button class="view-link ${state.morarjiYear===y?'year-selected':''}" data-year="${y}">${y}</button><div class="bar-track"><div class="bar-fill" style="width:${all.filter(r=>r.cohort===y&&r.result==='Passed').length/max*100}%;background:var(--brand)"></div></div><span class="bar-value">${all.filter(r=>r.cohort===y&&r.result==='Passed').length}</span></div>`).join('')+`<p class="chart-note">Select a year to update the follow-up summary below. Counts compare different cohorts; they do not measure change in the same children.</p>`)}${section('Compare the cohort sizes','Passing counts shown alongside exam-taking and pending results',cohortColumns(all,years))}</div><div class="section-head"><div><h2>${esc(state.morarjiYear)} cohort</h2><p>The follow-up summary uses this year.</p></div></div><div class="grid two-col" style="margin-top:22px">${section('After the exam','Track each step independently',bar('Selected',rows.filter(r=>r.selected).length,rows.length)+bar('Admitted',rows.filter(r=>r.admitted).length,rows.length)+bar('Scholarship received',rows.filter(r=>r.scholarship==='Received').length,rows.length)+`<p class="chart-note">An exam pass does not automatically mean selection, admission or scholarship receipt.</p>`)}</div>${state.role==='Leadership'?'':`<section class="card table-card"><div class="table-head"><div><h2>Cohort follow-up</h2><p>${esc(state.morarjiYear)} · update individual records</p></div></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Centre</th><th>Training days</th><th>Application</th><th>Exam result</th><th>Selected / admitted</th><th>Scholarship</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${db.students.some(s=>s.id===r.s.id)?`<button class="name-link" data-child="${r.s.id}">${esc(r.s.name)}</button>`:esc(r.s.name)}</td><td>${centreName(r.s.centre)}</td><td>${r.trainingDays??'Not recorded'}</td><td>${r.applied===null?'Not recorded':r.applied?'Applied':'Not applied'}</td><td>${badge(r.result,r.result==='Passed'?'green':r.result==='Not passed'?'red':'muted')}</td><td>${r.selected===null?'Unknown':r.selected?'Yes':'No'} / ${r.admitted===null?'Unknown':r.admitted?'Yes':'No'}</td><td>${esc(r.scholarship)}</td><td><button class="text-button" data-morarji="${r.s.id}">Update →</button></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No cohort records for the selected year and centres.')}</div></section>`}`;}

function guidance(){const ids=scope().map(c=>c.id),rows=db.guidance.filter(r=>ids.includes(r.centre)),contacted=rows.filter(r=>r.contact==='Contacted'),known=contacted.filter(r=>r.destination!=='Unknown');return head('Career guidance','See who was reached and where they went next. Record feedback and follow-up.',button('Add participant','new-guidance','primary','plus'))+filters({simple:true,cohort:true})+`<div class="notice neutral" style="margin-bottom:22px">${icon('info')}<p>January 2026 sample guidance cohort · Grades 10–12. Follow-up is a separate cohort view, independent of the CAC reporting month. Session frequency: twice a year.</p></div><div class="grid metrics">${metric('Career-guidance participants',rows.length,'January 2026 sample session','people')}${metric('Participants contacted after guidance',contacted.length,`${rows.length-contacted.length} still to contact`,'flag')}${metric('Participants with a destination recorded',known.length,'Includes self-reports; see verification','chart')}${metric('Participants with verified admission',known.filter(r=>r.verification==='Verified admission').length,'Evidence checked in sample records','check')}</div><div class="grid two-col">${section('Subject / course chosen','Keep unknown destinations visible',[...new Set(rows.map(r=>r.destination))].map(d=>bar(d,rows.filter(r=>r.destination===d).length,rows.length,d==='Unknown'?'amber':'blue')).join(''))}${section('Session feedback','Teacher-reported experience, not a measured confidence score',`<p class="chart-note">Use this space to record teachers’ feedback on how children experienced the session.</p><textarea id="guidance-feedback" rows="4" style="width:100%;margin:12px 0" aria-label="Teacher feedback">${esc(db.guidanceFeedback||'')}</textarea>${button('Save feedback','save-guidance-feedback','dark','check')}`)}</div><section class="card table-card"><div class="table-head"><div><h2>Subject / course chosen</h2><p>Record contact and destination with the evidence source</p></div></div><div class="table-scroll"><table><thead><tr><th>Participant</th><th>Centre</th><th>Grade</th><th>Contact</th><th>Subject / course chosen</th><th>Evidence</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${centreName(r.centre)}</td><td>${r.grade}</td><td>${esc(r.contact)}</td><td>${esc(r.destination)}</td><td>${r.contact==='Contacted'?esc(r.verification):'—'}</td><td><button class="text-button" data-guidance="${r.id}">Update →</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function donor(){const t=totals(),n=t.rows.length,marks=t.rows.filter(r=>r.score!==null),avg=scoreGroup(children()).avg??'—';return head('Donor summary','An aggregate view of the same centre records.',button('Print report','print-report','','download')+button('Back to overview','back-overview','','arrow'))+filters({simple:true})+`<div class="donor-cover"><img class="print-logo" src="mass-logo.jpg" alt="MASS NGO" width="80"><div><div class="eyebrow">MASS · Children’s Activity Centres</div><h2>${esc(state.donor||'All donor-supported centres')}</h2><p>${monthName()} · ${scope().length} sample centres · ${n} children</p></div><span class="donor-lock">Aggregate preview · no child names</span></div><div class="grid metrics" style="margin-top:22px">${metric('Students enrolled',n,'Across selected centres')}${metric('Present student-days',t.p,`${t.missing} unmarked entries`,'calendar')}${metric('Students with good engagement',t.good,'>20 days + 2+ activities','activity')}${metric(`${state.exam} average`,avg,`${marks.length} results · ${scoreGroup(children()).max?'out of '+scoreGroup(children()).max:'mixed scales'}`,'book')}</div>${morarjiScorecard()}<div class="grid two-col">${section('Attendance across funded centres','Monthly attendance %',chartCentres('attendance'))}${section('Activity participation','Students attending 2+ cultural/sports activities',chartCentres('activities'))}</div><div class="notice neutral">${icon('heart')}<p>This preview uses the same centre records filtered by donor. Donor access and historical funding periods still need agreement; no separate donor account has been created.</p></div>`;}
function render(){if(state.role==='Leadership'&&['daily','children','guidance'].includes(state.page))state.page='overview';const nav=navItems(),pageFn={overview,attendance,daily,learning,activities,children:roster,visits,morarji,guidance,donor};let pageContent=(pageFn[state.page]||overview)();const filterEnd=pageContent.indexOf('</div>',pageContent.indexOf('<div class="filters">'));if(filterEnd>=0&&pageContent.includes('<div class="filters">'))pageContent='<div class="workflow-header">'+pageContent.slice(0,filterEnd+6)+'</div>'+pageContent.slice(filterEnd+6);$('#app').innerHTML=`<div class="app ${state.menu?'menu-open':''} ${state.collapsed?'sidebar-collapsed':''}"><aside class="sidebar"><a class="brand" href="#" data-action="back-overview"><span class="mass-logo"><img src="mass-logo.jpg" alt="MASS NGO logo" width="201" height="160"></span></a><div class="workspace"><span class="eyebrow">Programme workspace</span><strong>Children’s Activity Centres</strong></div><button class="text-button collapse-nav" data-action="collapse-nav" aria-label="Toggle sidebar" aria-expanded="${!state.collapsed}">${icon('menu')}<span>Collapse menu</span></button><div class="nav-label">${state.role==='Teacher'?'Your centre':state.role==='Cluster Officer'?'Your cluster':'Programme'}</div><nav class="nav">${nav.map(([id,label,ic])=>`<button data-nav="${id}" title="${esc(label)}" class="${state.page===id?'active':''}">${icon(ic)}<span class="nav-text">${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="text-button" data-action="guide">${icon('info')} About this prototype</button><div class="mini-profile"><span class="avatar">${state.role==='Teacher'?'AP':state.role==='Cluster Officer'?'MK':'LT'}</span><div><strong>${state.role==='Teacher'?'Anita · Teacher':state.role==='Cluster Officer'?'Meera · Cluster officer':'Leadership team'}</strong><small>${state.role==='Teacher'?'Aralimatti · both shifts':state.role==='Cluster Officer'?'4 assigned sample centres':'All sample centres'}</small></div></div></div></aside><main class="shell"><header class="topbar"><div style="display:flex;gap:14px;align-items:center"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span class="mass-logo header-logo"><img src="mass-logo.jpg" alt="MASS NGO" width="201" height="160"></span><div class="breadcrumb"><span> / </span> <b>${state.role}</b></div></div><div class="top-actions"><span class="demo-chip">${liveReview?"Live imported records":"Sample data"}</span>${liveReview?`<a class="btn" href="?view=workspace">Open real data entry</a>`:""}<div class="role-switch"><label for="role">Preview as</label><select id="role">${['Leadership','Cluster Officer','Teacher'].map(r=>`<option ${state.role===r?'selected':''}>${r}</option>`).join('')}</select></div><button class="top-icon" data-action="guide" aria-label="Prototype guide">${icon('info')}</button></div></header><div class="content">${state.role!=='Leadership'?`<div class="record-tools"><button class="btn" data-action="manage-records">Correct / remove entries</button>${removalUndo?'<button class="btn" data-action="undo-remove">Undo last removal</button>':''}<small>Choose a record to correct or remove. Leaving the programme? Update enrolment status instead.</small></div>`:''}${pageContent}<div class="sample-note"><span>Fictional sample records · 6 demonstration centres · saved in this browser only</span><button class="text-button" data-action="guide">Rules & source download →</button></div></div></main><nav class="bottom-nav" aria-label="Mobile navigation">${nav.slice(0,4).map(([id,label,ic])=>`<button data-nav="${id}" title="${esc(label)}" class="${state.page===id?'active':''}">${icon(ic)}${label==='Daily Attendance'?'Attendance':label==='Activities & Engagement'?'Activities':label}</button>`).join('')}<button data-action="menu">${icon('menu')}More</button></nav></div>`;paginateTables($('#app'));}
function field(label,name,value='',type='text',extra=''){return `<label class="field ${extra}"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''}></label>`;}
function drop(label,name,options,value,extra=''){return `<label class="field ${extra}"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
let modalCallback=null,lastFocus=null;
function modal(title,subtitle,body,onSave=null,wide=false,saveLabel='Save changes'){lastFocus=document.activeElement;modalCallback=onSave;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="dialog-form"><div class="modal-body">${body}<p class="field-error" id="form-error" role="alert"></p></div><div class="modal-actions"><button type="button" class="btn" data-action="close">${onSave?'Cancel':'Close'}</button>${onSave?`<button class="btn primary" type="submit">${icon('check')}${saveLabel}</button>`:''}</div></form></section></div>`;$('#overlay').querySelector('input,select,textarea,button')?.focus();document.body.style.overflow='hidden';paginateTables($('#overlay'));}
function close(){ $('#overlay').innerHTML='';modalCallback=null;document.body.style.overflow='';lastFocus?.focus();}
function childDetail(id){const s=db.students.find(s=>s.id===id),r=stats(s);modal(esc(s.name),`${s.id} · ${centreName(s.centre)} · ${s.shift} · Grade ${s.grade}`,`<div class="detail-grid"><div><small>Attendance · ${monthName()}</small><strong>${r.p} days</strong>${badge(r.missing?'Incomplete':attendanceBand(r.p).label,r.missing?'muted':attendanceBand(r.p).tone)}</div><div><small>Activity participation</small><strong>${r.act} / ${r.held}</strong>${badge(activityBand(r.act,r.unknown).label,activityBand(r.act,r.unknown).tone)}</div><div><small>${state.exam} combined test</small><strong>${r.score??'—'} <small>/ ${r.maxMarks}${r.sample?' sample':''}</small></strong>${badge(recordedBand(r).label,recordedBand(r).tone)}</div></div><div style="margin:20px 0">${engagement(r)}<p class="chart-note">${r.missing} unmarked attendance entries · ${r.unknown} activity records missing.</p></div>${String(s.grade)==='10'?`<h3>Class 10 board exam</h3><p>Passed Class 10 board exam? <strong>${esc(s.boardPassed||'Not entered')}</strong></p>`:''}<h3>CAC attendance status · ${monthName()}</h3><p>${badge(dropoutStatus(s).status,dropoutStatus(s).tone)} ${esc(dropoutStatus(s).reason)}</p><h3>Exam history</h3>${['F1','F2','F3','F4'].map(ex=>bar(ex+' / '+scoreInfo(s,ex).maxMarks,db.scores[id]?.[ex]??null,scoreInfo(s,ex).maxMarks,'blue')+(db.scores[id]?.[ex]==null?'<small>Not recorded</small>':'')).join('')}<div class="divider"></div><h3>Teacher’s assessment notes</h3><p class="chart-note">${r.date?fmtDate(r.date):'Exam date not recorded'} · ${esc(r.performance||'No performance remarks recorded.')}</p><h3>Main challenge</h3><p class="chart-note">${esc(s.challenge||'Not recorded.')}</p><div class="divider"></div><p>${esc(db.followups[id]?.note||'No follow-up note yet.')}</p><div style="display:flex;gap:10px;margin-top:20px"><button class="btn" type="button" data-edit-child="${id}">${icon('people')}Edit profile</button><button class="btn dark" type="button" data-followup="${id}">${icon('flag')}Follow-up note</button></div>`,null,true);}
function editChild(id){const student=db.students.find(s=>s.id===id),s=student||{name:'',centre:scope()[0]?.id,grade:state.grade||'1',gender:'Girl',shift:state.shift||'Morning',enrolled:TODAY,challenge:''};modal(id?'Edit student profile':'Add student','Create the profile once. Attendance, activities and assessments use the same student ID.',`<div class="form-grid">${field('Full name','name',s.name,'text','full')}${drop('Centre / village','centre',scope().map(c=>[c.id,c.name]),s.centre)}${drop('Shift','shift',['Morning','Evening'],s.shift)}${drop('Grade','grade',Array.from({length:10},(_,i)=>String(i+1)),s.grade)}${drop('Gender','gender',['Girl','Boy'],s.gender)}<label class="field full" id="board-result-field" ${String(s.grade)==='10'?'':'hidden'}><span>Passed Class 10 board exam?</span><select name="boardPassed" ${String(s.grade)==='10'?'':'disabled'}><option value="">Select result</option>${['Yes','No'].map(v=>`<option value="${v}" ${s.boardPassed===v?'selected':''}>${v}</option>`).join('')}</select><small>Leave blank until the board-exam result is known.</small></label>${field('Enrolment date','enrolled',s.enrolled,'date','full')}${drop('Enrolment status','enrolmentStatus',['Active','CAC dropout','Left programme'],s.enrolmentStatus||(s.active===false?'Left programme':'Active'))}${field('Exit date (required when leaving)','exitDate',s.exitDate||'','date')}<label class="field full"><span>Main challenge (optional teacher note)</span><textarea name="challenge" rows="3">${esc(s.challenge||'')}</textarea></label>${id?'':`<label class="field-checkbox field full"><input type="checkbox" name="differentStudent"> If a possible match is found, I have checked that this is a different student.</label>`}</div><p class="form-help">Possible matches are checked by name, centre and grade. Records are never merged automatically. Keep personal notes relevant to learning and attendance.</p>`,f=>{if(!f.name?.trim()||!f.enrolled)throw Error('Enter a name and enrolment date.');if(f.enrolled>TODAY)throw Error('Enrolment date cannot be in the future.');if(!scope().some(c=>c.id===f.centre))throw Error('Choose an assigned centre.');const normal=n=>n.trim().toLowerCase().replace(/\s+/g,' '),match=db.students.find(c=>c.id!==id&&normal(c.name)===normal(f.name)&&c.centre===f.centre&&c.grade===f.grade);if(match&&!f.differentStudent)throw Error('Possible match: '+match.name+' ('+match.id+'). Check Student Profile first. If this is a different child, tick the confirmation above.');delete f.differentStudent;if(f.grade==='10'&&!['','Yes','No'].includes(f.boardPassed??''))throw Error('Choose Yes or No, or leave the board result blank.');if(f.enrolmentStatus!=='Active'&&(!f.exitDate||f.exitDate<f.enrolled||f.exitDate>TODAY))throw Error('For a student who has left, enter an exit date between enrolment and today.');if(f.enrolmentStatus==='Active'&&f.exitDate)throw Error('Clear the exit date for an active student.');f.active=f.enrolmentStatus==='Active';f.name=f.name.trim();if(id)Object.assign(s,f);else{const nextId='CAC-'+String(Math.max(...db.students.map(x=>+x.id.slice(4)),0)+1).padStart(3,'0');db.students.push({id:nextId,...f,note:''});db.scores[nextId]={F1:null,F2:null,F3:null,F4:null};}Object.assign(state,{centre:state.role==='Teacher'?'':f.centre,shift:f.shift,grade:'',gender:'',query:''});persist('Student profile saved · shared across records');});}

function followup(id){const s=db.students.find(s=>s.id===id),f=db.followups[id]||{};modal('Follow-up note',`${s.name} · ${centreName(s.centre)}`,`<div class="form-grid">${drop('Status','status',['To follow up','In progress','Completed'],f.status||'To follow up')}${field('Next contact date (optional)','date',f.date||'','date')}<label class="field full"><span>What needs attention?</span><textarea name="note" rows="4" required>${esc(f.note||'')}</textarea></label></div><p class="form-help">Record an observation or action. CAC dropout uses zero attendance for one full completed month with complete records; it does not establish school dropout or automatically close enrolment.</p>`,v=>{if(!v.note.trim())throw Error('Add a short follow-up note.');db.followups[id]={...v,updated:new Date().toISOString()};persist('Follow-up saved');});}
function enterMarks(){const list=children(),key=[state.exam,state.centre||'all',state.shift||'both'].join('|'),batch=db.assessmentBatches[key]||{};modal(`Enter ${state.exam} marks`,'One row per student · one date for the group',`<div class="form-grid">${field('Exam date','batchDate',batch.date||'','date','full')}</div><p class="form-help">Configured maximum marks are read-only. Zero is a score. Absent and not entered stay separate. Subject sections and maxima must be agreed with MASS before adding subject scores.</p><div class="table-scroll"><table><thead><tr><th>Student</th><th>Grade / shift</th><th>Status</th><th>Marks</th><th>Maximum</th></tr></thead><tbody>${list.map(c=>{const r=scoreInfo(c);return `<tr><td>${esc(c.name)}<div class="subtext">${c.id}</div></td><td>${c.grade} · ${c.shift}</td><td>${drop('Status for '+c.name,'status_'+c.id,['Recorded','Absent','Not entered'],r.status)}</td><td>${field('Marks for '+c.name,'score_'+c.id,r.score??'','number')}</td><td>${r.maxMarks}${r.sample?' (sample)':''}</td></tr>`;}).join('')}</tbody></table></div><label class="field full"><span>Overall assessment comment (optional)</span><textarea name="overall" rows="3">${esc(batch.comment||'')}</textarea></label>`,f=>{const updates=[];for(const c of list){const r=scoreInfo(c),v=f['score_'+c.id],status=f['status_'+c.id],changed=v!==(r.score===null?'':String(r.score))||status!==r.status||!!f.batchDate;if(!changed)continue;if(status==='Recorded'&&(v===''||!Number.isInteger(+v)||+v<0||+v>r.maxMarks))throw Error('Enter whole marks from 0 to '+r.maxMarks+' for '+c.name+'.');if(status!=='Recorded'&&v!=='')throw Error('Clear marks for '+c.name+' when '+status+'.');const date=f.batchDate||r.date;if(status==='Recorded'&&!date)throw Error('Enter the group exam date.');if(date>TODAY)throw Error('Exam date cannot be in the future.');updates.push({c,v,status,date,r});}for(const {c,v,status,date,r} of updates){db.scores[c.id]??={};db.scores[c.id][state.exam]=status==='Recorded'?+v:null;db.assessmentDetails[c.id+'|'+state.exam]={...db.assessmentDetails[c.id+'|'+state.exam],year:'2026–27',maxMarks:r.maxMarks,status,date};}db.assessmentBatches[key]={date:f.batchDate||batch.date||'',comment:f.overall};persist('Assessment saved');},true,'Save marks');}
function eventEdit(id){activitySession(id);}
function sessionEntry(){modal('Update CAC session','One planned session per centre, shift and date.',`<div class="form-grid">${drop('Centre','centre',scope().map(c=>[c.id,c.name]),scope()[0]?.id)}${drop('Shift','shift',['Morning','Evening'],state.shift||'Morning')}${field('Session date','date',state.date,'date')}${drop('Status','status',['Planned','Held','Cancelled'],'Held')}</div><p class="form-help">A child marked present does not automatically mark a session held.</p>`,f=>{if(!scope().some(c=>c.id===f.centre))throw Error('Choose an assigned centre.');if(!f.date)throw Error('Choose a session date.');if(f.status==='Held'&&f.date>TODAY)throw Error('Future sessions must remain planned.');const found=db.sessions.find(r=>r.centre===f.centre&&r.shift===f.shift&&r.date===f.date);if(found)Object.assign(found,f);else db.sessions.push(f);persist('Session status saved');});}
function newActivity(){activitySession();}
function activityPlanReference(){return `<details class="card plan-reference" style="margin:22px 0"><summary>Annual activity plan · field photo reference</summary><p class="chart-note">The photographed plan runs May 2026–April 2027. Planned items below do not count as held events or child participation.</p><div class="table-scroll"><table><thead><tr><th>Planned item</th><th>Calendar reference</th><th>System entry</th></tr></thead><tbody><tr><td>CAC classes</td><td>24 days/month, June–April</td><td>Confirm actual held centre/shift days</td></tr><tr><td>Cultural activities</td><td>2/month, June–April</td><td>First and third Saturday; editable name</td></tr><tr><td>Sports activities</td><td>2/month, June–April</td><td>Second and fourth Saturday; editable name</td></tr><tr><td>Important days</td><td>Named observances vary by month</td><td>Add as separate Important day events</td></tr><tr><td>Other annual-plan items</td><td>Jatha, orientation, child-list/baseline update, parents’ meetings, children’s parliament, adolescent girls’ meetings and youth-group meetings</td><td>Reference only; tracking scope must be agreed separately</td></tr></tbody></table></div></details>`;}
function activityEntry(){const ev=activityEvents();modal('Choose an activity','Open an activity to record or correct each child’s participation.',`<div class="attention-list">${ev.map(e=>`<div class="attention-item"><div style="flex:1"><strong>${centreName(e.centre)} · ${esc(e.name)}</strong><p>${fmtDate(e.date)} · ${e.category} · ${e.status}</p></div><button type="button" class="btn tiny" data-event="${e.id}">Open →</button></div>`).join('')||empty('No activities match this selection.')}</div>`,null,true);}
function newVisit(id){const existing=db.visits.find(v=>v.id===id);modal(existing?'Edit centre visit':'Record a centre visit','Two morning and two evening visits per centre, each month.',`<div class="form-grid">${drop('Centre','centre',scope().map(c=>[c.id,c.name]),existing?.centre||state.centre||scope()[0]?.id)}${drop('Shift','shift',['Morning','Evening'],existing?.shift||'Morning')}${field('Visit date','date',existing?.date||TODAY,'date')}${drop('Status','status',['Completed','Planned'],existing?.status||'Completed')}<label class="field full"><span>Centre feedback</span><textarea rows="3" name="feedback" required>${esc(existing?.feedback||'')}</textarea></label><label class="field full"><span>Next action</span><textarea rows="2" name="action">${esc(existing?.action||'')}</textarea></label></div>`,f=>{if(!f.date||!f.feedback.trim())throw Error('Add the visit date and centre feedback.');if(f.status==='Completed'&&f.date>TODAY)throw Error('A future visit must be planned, not completed.');const c=centres.find(c=>c.id===f.centre);if(!scope().some(x=>x.id===f.centre))throw Error('Choose an assigned centre.');if(existing)Object.assign(existing,{officer:c.officer,...f});else db.visits.push({id:'V-'+Date.now(),officer:c.officer,...f});persist('Visit saved');});}
function editMorarji(id){const historic=db.morarjiHistory.find(r=>r.s.id===id),r=db.morarji[id]||historic,s=db.students.find(s=>s.id===id)||historic?.s;modal('Morarji follow-up',`${s.name} · ${r.cohort} cohort`, `<div class="form-grid">${field('Training days attended','trainingDays',r.trainingDays,'number')}${drop('Applied for exam?','applied',[['null','Unknown'],['true','Yes'],['false','No']],String(r.applied))}${drop('Took the exam?','took',[['null','Unknown'],['true','Yes'],['false','No']],String(r.took))}${drop('Exam result','result',['Pending','Passed','Not passed','Not applied'],r.result)}${drop('Selected?','selected',[['null','Unknown'],['true','Yes'],['false','No']],String(r.selected))}${drop('Admitted?','admitted',[['null','Unknown'],['true','Yes'],['false','No']],String(r.admitted))}${drop('Scholarship receipt','scholarship',['Not recorded','Pending','Received'],r.scholarship,'full')}</div>`,f=>{if(f.trainingDays!==''&&(!Number.isInteger(+f.trainingDays)||+f.trainingDays<0))throw Error('Training days must be a non-negative whole number.');if(f.applied==='false'&&f.took==='true')throw Error('Check the application and exam-attendance entries.');if(f.took!=='true'&&['Passed','Not passed'].includes(f.result))throw Error('A pass/fail result requires the child to have taken the exam.');if(f.admitted==='true'&&f.selected!=='true')throw Error('Check selection before recording admission.');Object.assign(r,f,{trainingDays:f.trainingDays===''?null:+f.trainingDays,applied:f.applied==='null'?null:f.applied==='true',took:f.took==='null'?null:f.took==='true',selected:f.selected==='null'?null:f.selected==='true',admitted:f.admitted==='null'?null:f.admitted==='true'});persist('Morarji follow-up saved');});}
function editGuidance(id){const r=db.guidance.find(g=>g.id===id);modal('Career guidance follow-up',`${r.name} · ${centreName(r.centre)}`,`<div class="form-grid">${field('Follow-up date','followup',r.followup,'date')}${drop('Contact status','contact',['Contacted','Not contacted'],r.contact)}${drop('Destination','destination',['Unknown','Class 11 — Arts','Class 11 — Science','Class 12','ITI — Electrical','Diploma course'],r.destination,'full')}${drop('Evidence source','verification',['Self-reported','Verified admission'],r.verification,'full')}</div>`,f=>{if(f.contact==='Not contacted'&&f.destination!=='Unknown')throw Error('Uncontacted participants should remain Unknown until a destination is reported.');if(!f.followup||f.followup>TODAY)throw Error('Enter a follow-up date on or before today.');Object.assign(r,f);persist('Career follow-up saved');});}
let removalUndo=null,recordKind='Attendance';
function managedRecords(kind=recordKind){if(state.role==='Leadership')return [];const permitted=centres.filter(c=>state.role==='Teacher'?c.id==='C01':c.officer==='Meera').map(c=>c.id),students=db.students.filter(s=>permitted.includes(s.centre)),ids=new Set(students.map(s=>s.id)),out=[],add=(key,label,detail)=>out.push({key,label,detail});
if(kind==='Students')students.forEach(s=>add(s.id,s.name,s.id+' · '+centreName(s.centre)+' · '+s.shift));
if(kind==='Attendance')Object.entries(db.attendance).forEach(([key,v])=>{const [id,date]=key.split('|'),s=students.find(s=>s.id===id);if(s&&date===state.date)add(key,s.name,date+' · '+centreName(s.centre)+' · '+v);});
if(kind==='Exam results')students.forEach(s=>['F1','F2','F3','F4'].forEach(ex=>{const r=scoreInfo(s,ex);if(r.score!==null||r.status!=='Not entered')add(s.id+'|'+ex,s.name,ex+' · '+r.status+' · '+(r.score??'—')+' / '+r.maxMarks);}));
if(kind==='Activities')db.events.filter(e=>permitted.includes(e.centre)).forEach(e=>add(e.id,e.name,e.date+' · '+centreName(e.centre)+' · '+e.status));
if(kind==='CAC sessions')db.sessions.filter(e=>permitted.includes(e.centre)).forEach(e=>add([e.centre,e.shift,e.date].join('|'),centreName(e.centre),e.date+' · '+e.shift+' · '+e.status));
if(kind==='Visits'&&state.role==='Cluster Officer')db.visits.filter(e=>permitted.includes(e.centre)).forEach(e=>add(e.id,centreName(e.centre),e.date+' · '+e.shift+' · '+e.status));
if(kind==='Morarji')morarjiRows(true).forEach(r=>{if(permitted.includes(r.s.centre))add(r.s.id,r.s.name,r.cohort+' · '+r.result);});
if(kind==='Follow-up notes')Object.keys(db.followups).filter(id=>ids.has(id)).forEach(id=>add(id,students.find(s=>s.id===id).name,db.followups[id].note));return out;}
function manageRecords(){if(state.role==='Leadership')return;const kinds=['Attendance','Exam results','Activities','CAC sessions','Students','Morarji','Follow-up notes',...(state.role==='Cluster Officer'?['Visits']:[])];if(!kinds.includes(recordKind))recordKind='Attendance';const rows=managedRecords();modal('Correct / remove entries','Only your assigned centres · all records except attendance, which uses the selected date.',`<label class="field"><span>Record type</span><select id="record-kind">${kinds.map(k=>`<option ${k===recordKind?'selected':''}>${k}</option>`).join('')}</select></label>${recordKind==='Attendance'?`<label class="field"><span>Attendance date</span><input type="date" id="record-date" value="${state.date}" max="${TODAY}"></label>`:''}<p class="form-help">Removal makes an entry unrecorded, never absent or zero. You can undo the last removal until another change is saved or the page is reloaded. Remove a student only if the profile was entered by mistake; use enrolment status for a genuine exit.</p><div class="table-scroll"><table><thead><tr><th>Record</th><th>Details</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.detail)}</td><td><button type="button" class="btn tiny" data-record-edit="${esc(r.key)}">Edit</button> <button type="button" class="btn tiny remove-button" data-record-remove="${esc(r.key)}">Remove</button></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No saved entries in this selection.')}</div>`,null,true);}
function removeRecord(key){const record=managedRecords().find(r=>r.key===key);if(!record)return;const kind=recordKind,detail=kind==='Students'?'This removes the profile and its attendance, exam results, activity participation, follow-up note and current Morarji link. Use enrolment status instead if the student has actually left.':kind==='Activities'?'This removes the activity session and its child participation entries.':kind==='CAC sessions'?'This removes only the session record. Existing child attendance stays unchanged and must be reviewed separately.':'Only this saved record will be removed. Missing is not absence, failure or zero.';modal('Remove this entry?',record.label+' · '+record.detail,`<p>${esc(detail)}</p><p>You can undo this removal before another change is saved or this page is reloaded.</p>`,()=>{if(!managedRecords(kind).some(r=>r.key===key))throw Error('This record is no longer available in your assigned centres.');const snapshot=JSON.stringify(db);if(kind==='Students'){db.students=db.students.filter(s=>s.id!==key);for(const bucket of ['attendance','participation','assessmentDetails'])for(const k of Object.keys(db[bucket]||{}))if(k.startsWith(key+'|'))delete db[bucket][k];delete db.scores[key];delete db.followups[key];delete db.morarji[key];}if(kind==='Attendance')delete db.attendance[key];if(kind==='Exam results'){const [id,ex]=key.split('|');delete db.scores[id][ex];delete db.assessmentDetails[key];}if(kind==='Activities'){db.events=db.events.filter(e=>e.id!==key);for(const k of Object.keys(db.participation))if(k.endsWith('|'+key))delete db.participation[k];}if(kind==='CAC sessions')db.sessions=db.sessions.filter(e=>[e.centre,e.shift,e.date].join('|')!==key);if(kind==='Visits')db.visits=db.visits.filter(e=>e.id!==key);if(kind==='Morarji'){delete db.morarji[key];db.morarjiHistory=db.morarjiHistory.filter(r=>r.s.id!==key);}if(kind==='Follow-up notes')delete db.followups[key];persist('Entry removed · use Undo last removal to restore');removalUndo={snapshot,role:state.role,savedAt:db.lastSaved};},false,'Remove entry');}
function undoRemoval(){if(!removalUndo||state.role!==removalUndo.role||db.lastSaved!==removalUndo.savedAt){removalUndo=null;toast('Undo is unavailable after another saved change or role switch.');render();return;}db=JSON.parse(removalUndo.snapshot);removalUndo=null;persist('Removed entry restored');render();}
function editManagedRecord(key){if(!managedRecords().some(r=>r.key===key))return;const [id,ex]=key.split('|');if(recordKind==='Students')return editChild(key);if(recordKind==='Exam results'){state.centre='';state.shift='';state.grade='';state.gender='';state.query='';return editLearningRow(id);}if(recordKind==='Activities')return eventEdit(key);if(recordKind==='Visits')return newVisit(key);if(recordKind==='Morarji')return editMorarji(key);if(recordKind==='Follow-up notes')return followup(key);if(recordKind==='Attendance')return modal('Correct attendance',key,drop('Attendance code','code',['P','A','H'],db.attendance[key]),f=>{db.attendance[key]=f.code;persist('Attendance corrected');});if(recordKind==='CAC sessions'){const r=db.sessions.find(e=>[e.centre,e.shift,e.date].join('|')===key);modal('Correct CAC session',centreName(r.centre)+' · '+r.shift+' · '+r.date,drop('Session status','status',['Planned','Held','Cancelled'],r.status),f=>{if(f.status==='Held'&&r.date>TODAY)throw Error('A future session cannot be held.');r.status=f.status;persist('Session corrected');});}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||state.role==='Leadership')return;if(b.dataset.recordRemove)removeRecord(b.dataset.recordRemove);else if(b.dataset.recordEdit)editManagedRecord(b.dataset.recordEdit);else if(b.dataset.action==='manage-records')manageRecords();else if(b.dataset.action==='undo-remove')undoRemoval();});
document.addEventListener('change',e=>{if(e.target.id==='record-kind'){recordKind=e.target.value;manageRecords();}if(e.target.id==='record-date'){if(!e.target.value||e.target.value>TODAY){toast('Choose a valid date on or before the sample date.');return;}state.date=e.target.value;manageRecords();}});
function guide(){modal('About this prototype','A first interactive design for MASS — not a live student database.',`<div class="help-grid"><div class="help-item"><h3>Initial release</h3><p>Career Guidance is retained for later and hidden from the initial navigation.</p><button type="button" class="btn" data-action="later-modules">${state.laterModules?'Use initial-release navigation':'Preview later modules'}</button><h3>Three working views</h3><p>Teacher: own centre, both shifts. Cluster officer: assigned centres. Leadership: all centres and donor aggregates. The role switch is for preview; production permissions need a backend.</p></div><div class="help-item"><h3>One connected experience</h3><p>Attendance, activities, marks and follow-ups update the same records. Changes save in this browser and update charts immediately. They do not sync to other users.</p></div><div class="help-item"><h3>Confirmed engagement rule</h3><p>More than 20 days present AND at least two activities. Green is good engagement, not an award. Missing records remain visible.</p></div><div class="help-item"><h3>PM review needed</h3><p>Real combined-test maximum; 0–8 band label; actual operating-day calendar and holiday handling; definition of low activity participation; donor funding dates and access; correction audit/approval policy.</p></div></div><div class="divider"></div><h3>Attendance bands</h3><p class="chart-note">Below 15 low · 15 average · 16–20 good · 21–25 very good. Monthly sample calendar: 24 non-Sunday operating days. October is month-to-date.</p><h3>Activities</h3><p class="chart-note">Four Saturdays: cultural on the first and third, sports on the second and fourth. “Below two” is a provisional low-participation flag for review, not an agreed award rule.</p><div class="divider"></div><a class="btn primary" href="MASS-CAC-Vercel-Source.zip" download>${icon('download')}Download Vercel-ready source</a><button type="button" class="btn" data-action="export" style="margin-left:8px">${icon('download')}Export current summary</button><p class="form-help">All child, officer and donor mappings here are fictional sample records. Do not enter real personal information in this preview.</p><button type="button" class="text-button" data-action="reset-demo">Reset sample records</button>`,null,true);}
function csvExport(){const rows=(state.role==='Leadership'||state.page==='donor')?[['Centre','Active children','Present student-days','Good engagement'],...scope().map(c=>{const t=totals(children().filter(s=>s.centre===c.id));return [c.name,t.rows.length,t.p,t.good];})]:[['Child ID','Name','Centre','Shift','Grade','Month','Present','Unmarked','Activities attended','Activity records missing',state.exam,'Good engagement'],...totals().rows.map(r=>[r.s.id,r.s.name,centreName(r.s.centre),r.s.shift,r.s.grade,state.month,r.p,r.missing,r.act,r.unknown,r.score??'',r.good?'Yes':'No'])];const a=document.createElement('a'),url=URL.createObjectURL(new Blob([rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv'}));a.href=url;a.download='MASS-'+(state.role==='Leadership'||state.page==='donor'?'centre-aggregate':'student-summary')+'-'+state.month+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Current selection exported');}
function navigate(page){if(state.role==='Leadership'&&['daily','children','guidance'].includes(page))page='overview';if(page==='guidance'&&!state.laterModules)return;if(state.role==='Teacher'&&['donor','visits'].includes(page))page='daily';if(page!=='donor'&&page!=='overview')state.donor='';if(['donor','visits','morarji','guidance'].includes(page))Object.assign(state,{shift:'',grade:'',gender:'',officer:''});state.page=page;state.grade='';state.gender='';state.officer='';state.menu=false;tablePages={};state.engagementFilter='';state.query='';render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(state.role==='Leadership'&&(b.dataset.child||b.dataset.editMarks||b.dataset.editChild||b.dataset.followup||b.dataset.event||b.dataset.morarji||b.dataset.guidance||b.dataset.mark))return;if(b.matches('a[data-action]'))e.preventDefault();if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.gender){state.gender=state.gender===b.dataset.gender?'':b.dataset.gender;tablePages={};render();return;}if(b.dataset.centre){state.centre=b.dataset.centre;render();return;}if(b.dataset.year){state.morarjiYear=b.dataset.year;render();return;}if(b.dataset.child){childDetail(b.dataset.child);return;}if(b.dataset.editMarks){editLearningRow(b.dataset.editMarks);return;}if(b.dataset.editChild){editChild(b.dataset.editChild);return;}if(b.dataset.followup){followup(b.dataset.followup);return;}if(b.dataset.event){eventEdit(b.dataset.event);return;}if(b.dataset.morarji){editMorarji(b.dataset.morarji);return;}if(b.dataset.guidance){editGuidance(b.dataset.guidance);return;}if(b.hasAttribute('data-shift')){state.shift=b.dataset.shift;render();return;}if(b.dataset.mark){const [id,code]=b.dataset.mark.split('|');const s=db.students.find(s=>s.id===id);if(!children().some(x=>x.id===id)||state.date<s.enrolled)return toast('Attendance cannot be entered before enrolment.');if(db.attendance[id+'|'+state.date]===code)return;db.attendance[id+'|'+state.date]=code;persist(`${s.name.split(' ')[0]} · ${db.attendance[id+'|'+state.date]?'marked '+code:'entry cleared'} · saved`);render();return;}const action=b.dataset.action;if(!action)return;if(state.role==='Leadership'&&['open-daily','new-child','enter-marks','activity-entry','new-activity','session-entry','new-visit','new-morarji','new-guidance','mark-all','mark-all-absent','mark-holiday','save-default-attendance','save-guidance-feedback'].includes(action))return;switch(action){case 'collapse-nav':state.collapsed=!state.collapsed;render();break;case 'later-modules':state.laterModules=!state.laterModules;close();if(!state.laterModules&&state.page==='guidance')state.page='overview';render();break;case 'print-report':window.print();break;case 'new-morarji':newMorarji();break;case 'new-guidance':newGuidance();break;case 'menu':state.menu=!state.menu;render();break;case 'close':close();break;case 'guide':guide();break;case 'donor':navigate('donor');break;case 'open-morarji':navigate('morarji');break;case 'reset-morarji':state.centre='';state.morarjiYear='2025–26';render();break;case 'back-overview':navigate(state.role==='Teacher'?'daily':'overview');break;case 'open-daily':navigate('daily');break;case 'monthly-attendance':state.month=state.date.slice(0,7);navigate('attendance');break;case 'new-child':editChild();break;case 'enter-marks':enterMarks();break;case 'activity-entry':activityEntry();break;case 'new-activity':newActivity();break;case 'session-entry':sessionEntry();break;case 'new-visit':newVisit();break;case 'reset-filters':Object.assign(state,{centre:'',shift:'',grade:'',gender:'',officer:'',donor:'',query:'',concerns:false,engagementFilter:'',month:TODAY.slice(0,7),exam:'F2',comparison:'F1|F2',fromExam:'F1',toExam:'F2'});render();break;case 'prev-date':case 'next-date':{const d=new Date(state.date+'T12:00:00');d.setDate(d.getDate()+(action==='prev-date'?-1:1));state.date=d.toISOString().slice(0,10);render();break;}case 'save-default-attendance':{const list=children().filter(s=>state.date>=s.enrolled);if(state.date>TODAY)return toast('Choose a date on or before the sample date.');let count=0;for(const s of list)if(!db.attendance[s.id+'|'+state.date]){db.attendance[s.id+'|'+state.date]='P';count++;}persist(`${count} default Present entries saved; existing codes preserved`);render();break;}case 'mark-all':case 'mark-all-absent':case 'mark-holiday':{const code=action==='mark-all'?'P':action==='mark-all-absent'?'A':'H',list=children().filter(s=>state.date>=s.enrolled);modal(code==='P'?'Mark visible children present?':code==='A'?'Mark visible children absent?':'Mark this group on holiday?',`${list.length} children · ${fmtDate(state.date)}`,`<p>Existing entries for the children currently shown will change to <strong>${code==='P'?'Present':code==='A'?'Absent':'Holiday'}</strong>. You can correct individual records afterwards.</p>`,()=>{list.forEach(s=>db.attendance[s.id+'|'+state.date]=code);persist(`${list.length} attendance entries saved`);},false,'Confirm and save');break;}case 'save-guidance-feedback':db.guidanceFeedback=$('#guidance-feedback').value;persist('Teacher feedback saved');break;case 'export':csvExport();break;case 'reset-demo':modal('Reset sample records?','This affects only this browser.',`<p>Your prototype edits will be replaced with the original fictional sample records.</p>`,()=>{db=seed();db.assessmentDetails={};db.assessmentBatches={};persist('Sample records reset');},false,'Reset sample records');break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='grade'){const board=document.querySelector('#board-result-field');if(board){board.hidden=el.value!=='10';board.querySelector('select').disabled=el.value!=='10';}}if(el.name?.startsWith('status_')&&el.value!=='Recorded'){const score=document.querySelector('[name=\"score_'+el.name.slice(7)+'\"]');if(score)score.value='';}if(el.id==='role'){close();Object.assign(state,{role:el.value,page:el.value==='Teacher'?'daily':'overview',centre:'',shift:'',grade:'',gender:'',donor:'',officer:'',query:'',concerns:false,engagementFilter:''});render();window.scrollTo(0,0);}else if(el.dataset.filter){state[el.dataset.filter]=el.value;if(['officer','donor'].includes(el.dataset.filter)&&state.centre&&!scope().some(c=>c.id===state.centre))state.centre='';if(liveReview&&['centre','donor'].includes(el.dataset.filter)){const available=db.students.filter(x=>scope().some(c=>c.id===x.centre));for(const key of ['shift','grade','gender'])if(state[key]&&!available.some(x=>x[key]===state[key]))state[key]='';}if(el.dataset.filter==='comparison')[state.fromExam,state.toExam]=el.value.split('|');tablePages={};render();}else if(el.id==='attendance-date'){if(!el.value||el.value>TODAY){toast('Select a date on or before 20 October 2026.');render();return;}state.date=el.value;render();}else if(el.id==='concerns'){state.concerns=el.checked;render();}});
document.addEventListener('input',e=>{if(e.target.name?.startsWith('score_')&&e.target.value!==''){const status=document.querySelector('[name=\"status_'+e.target.name.slice(6)+'\"]');if(status)status.value='Recorded';}if(e.target.id==='student-search'){const pos=e.target.selectionStart;state.query=e.target.value;const y=window.scrollY;render();$('#student-search')?.focus();$('#student-search')?.setSelectionRange(pos,pos);window.scrollTo(0,y);}});
document.addEventListener('submit',e=>{if(e.target.id!=='dialog-form')return;e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));if(modalCallback?.(values)===false)return;close();render();}catch(err){$('#form-error').textContent=err.message;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();if(state.menu){state.menu=false;render();}}if(e.key==='Tab'&&$('#overlay').children.length){const nodes=[...$('#overlay').querySelectorAll('button,a,input,select,textarea')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close();});
render();
